                </Button>
              )}
              <Button
                onClick={() => {
                  setShowPassengerCount(false);
                  setPassengerCount(1);
                }}
                variant="outline"
                className="w-full py-6 text-lg font-semibold"
              >
                Cancel
              </Button>
            </div>
          </div>
        </div>
      )}

      {/* Booking Confirmation Modal */}
      {showBookingConfirm && (
        <div className="fixed inset-0 bg-black/50 z-[2000] flex items-end">
          <div className="bg-white w-full rounded-t-3xl p-6">
            <h2 className="text-2xl font-bold text-[#121212] mb-6">Confirm Booking</h2>

            {/* Trip Details */}
            <div className="space-y-4 mb-6">
              <div className="flex items-start gap-3">
                <Navigation className="w-5 h-5 text-[#E11D48] mt-1" />
                <div>
                  <p className="text-sm text-[#64748B]">Pickup</p>
                  <p className="font-semibold text-[#121212]">{pickup}</p>
                </div>
              </div>
              <div className="flex items-start gap-3">
                <Navigation className="w-5 h-5 text-green-600 mt-1" />
                <div>
                  <p className="text-sm text-[#64748B]">Drop-off</p>
                  <p className="font-semibold text-[#121212]">{dropoff}</p>
                </div>
              </div>
            </div>

            {/* Ride Type */}
            <div className="bg-[#FFF1F2] border-2 border-[#E11D48] rounded-xl p-4 mb-6">
              <div className="flex items-center justify-between">
                <div className="flex items-center gap-3">
                  <span className="text-4xl">{selectedVehicle === 'share' ? '' : ''}</span>
                  <div>
                    <p className="font-bold text-[#121212]">
                      {selectedVehicle === 'share' ? 'Share Ride' : 'Special Ride'}
                    </p>
                    <p className="text-sm text-[#64748B]">
                      {selectedVehicle === 'share' ? 'Shared with others' : 'Private ride'}
                    </p>
                  </div>
                </div>
                <p className="text-2xl font-bold text-[#E11D48]">₱{getPrice()}</p>
              </div>
            </div>

            {/* Payment Method */}
            <div className="mb-6">
              <p className="text-sm font-semibold text-[#64748B] mb-3">Payment Method</p>
              <div className="grid grid-cols-2 gap-3">
                <button
                  onClick={() => setPaymentMethod('GCASH')}
                  className={`p-4 border-2 rounded-xl transition-all ${
                    paymentMethod === 'GCASH'
                      ? 'border-[#E11D48] bg-[#FFF1F2]'
                      : 'border-[#E2E8F0]'
                  }`}
                >
                  <div className="flex flex-col items-center gap-2">
                    <CreditCard className="w-6 h-6 text-[#0066FF]" />
                    <span className="font-semibold text-[#121212]">GCash</span>
                  </div>
                </button>
                <button
                  onClick={() => setPaymentMethod('COD')}
                  className={`p-4 border-2 rounded-xl transition-all ${
                    paymentMethod === 'COD'
                      ? 'border-[#E11D48] bg-[#FFF1F2]'
                      : 'border-[#E2E8F0]'
                  }`}
                >
                  <div className="flex flex-col items-center gap-2">
                    <span className="text-2xl"></span>
                    <span className="font-semibold text-[#121212]">Cash</span>
                  </div>
                </button>
              </div>
            </div>

            {/* Action Buttons */}
            <div className="space-y-3">
              <Button
                onClick={handleConfirmBooking}
                className="w-full bg-[#E11D48] hover:bg-[#BE123C] text-white py-6 text-lg font-bold uppercase"
              >
                Confirm Booking
              </Button>
              <Button
                onClick={() => setShowBookingConfirm(false)}
                variant="outline"
                className="w-full py-6 text-lg font-semibold"
              >
                Cancel
              </Button>
            </div>
          </div>
        </div>
      )}

      {/* Searching for Driver Modal */}
      {rideStatus === 'searching' && !isSearchMinimized && (
        <div className="fixed inset-0 bg-black/50 z-[2000] flex items-center justify-center p-4">
          <Card className="bg-white p-8 max-w-sm w-full text-center relative">
            {/* Minimize Button */}
            <button
              onClick={() => setIsSearchMinimized(true)}
              className="absolute top-4 right-4 w-8 h-8 flex items-center justify-center rounded-full bg-[#F1F5F9] hover:bg-[#E2E8F0] transition-colors"
            >
              <ChevronDown className="w-5 h-5 text-[#64748B]" />
            </button>

            <div className="w-20 h-20 bg-[#FFF1F2] rounded-full flex items-center justify-center mx-auto mb-4 animate-pulse">
              <span className="text-4xl"></span>
            </div>
            <h3 className="text-xl font-bold text-[#121212] mb-2">Finding a Driver...</h3>
            <p className="text-[#64748B] mb-6">Please wait while we find you a nearby driver</p>
            <Button
              onClick={handleCancelRide}
              variant="outline"
              className="w-full"
            >
              Cancel Request
            </Button>
          </Card>
        </div>
      )}

      {/* Minimized Floating Icon */}
      {rideStatus === 'searching' && isSearchMinimized && (
        <button
          onClick={() => setIsSearchMinimized(false)}
          className="fixed bottom-24 right-4 z-[2000] w-16 h-16 bg-[#E11D48] rounded-full shadow-2xl flex items-center justify-center hover:bg-[#BE123C] transition-all hover:scale-110"
        >
          <div className="relative">
            <span className="text-3xl animate-pulse"></span>
            <div className="absolute -top-1 -right-1 w-3 h-3 bg-green-500 rounded-full animate-ping"></div>
            <div className="absolute -top-1 -right-1 w-3 h-3 bg-green-500 rounded-full"></div>
          </div>
        </button>
      )}

      {/* Share Ride Lobby */}
      {showShareLobby && (
        <ShareRideLobby
          pickup={pickup}
          pickupAddress={pickupAddress}
          dropoff={dropoff}
          dropoffAddress={dropoffAddress}
          passengerCount={passengerCount}
          pricePerSeat={sharedRidePrice}
          onDriverFound={(lobbyId) => {
            // Don't close the lobby - let customers see driver info in the lobby itself
            // Just update the status for tracking
            setRideStatus('driver-found');
            console.log('✅ Driver found for lobby:', lobbyId);
          }}
          onClose={() => {
            setShowShareLobby(false);
          }}
        />
      )}

      {/* Lobby List Modal */}
      {showLobbyList && (
        <LobbyList
          dropoff={dropoff}
          onJoinLobby={(lobby) => {
            // Set the user's pickup to their selected location
            // Join the lobby with the selected pickup
            setShowLobbyList(false);
            setShowShareLobby(true);
          }}
          onClose={() => {
            setShowLobbyList(false);
          }}
        />
      )}

      {/* Driver Accepted Popup */}
      {driverAcceptedPopup && (
        <div className="fixed inset-0 bg-black/50 z-[3000] flex items-center justify-center p-4">
          <Card className="bg-white p-8 max-w-sm w-full text-center animate-in fade-in zoom-in duration-300">
            <div className="mb-4">
              <div className="w-20 h-20 bg-[#E11D48] rounded-full flex items-center justify-center mx-auto mb-4 text-4xl">
                {driverAcceptedPopup.driverPhoto}
              </div>
              <h3 className="text-2xl font-bold text-[#121212] mb-2">Driver Found! </h3>
              <p className="text-[#64748B] mb-4">Your driver is on the way</p>
            </div>

            {/* Driver Details */}
            <div className="bg-[#F8F9FA] rounded-xl p-4 mb-6 space-y-3">
              <div className="flex items-center justify-between">
                <span className="text-sm text-[#64748B] font-semibold">Driver Name</span>
                <span className="font-bold text-[#121212]">{driverAcceptedPopup.driverName}</span>
              </div>
              <div className="flex items-center justify-between">
                <span className="text-sm text-[#64748B] font-semibold">Plate Number</span>
                <span className="font-bold text-[#121212]">{driverAcceptedPopup.driverPlate}</span>
              </div>
              <div className="flex items-center justify-between">
                <span className="text-sm text-[#64748B] font-semibold">Rating</span>
                <span className="font-bold text-[#E11D48]">⭐ {driverAcceptedPopup.driverRating}</span>
              </div>
            </div>

            <Button
              onClick={() => setDriverAcceptedPopup(null)}
              className="w-full bg-[#E11D48] hover:bg-[#BE123C] text-white py-3 text-lg font-bold"
            >
              Got it! 
            </Button>
          </Card>
        </div>
      )}

      {/* Driver Status Update Popup */}
      {driverStatusPopup && (
        <div className="fixed inset-0 bg-black/50 z-[3000] flex items-end">
          <div className="bg-white w-full rounded-t-3xl p-6 animate-in slide-in-from-bottom duration-300">
            <div className="max-w-sm mx-auto">
              {/* Status Icon */}
              <div className="w-16 h-16 bg-gradient-to-br from-[#E11D48] to-[#BE123C] rounded-full flex items-center justify-center mx-auto mb-4 text-3xl">
                {driverStatusPopup.status === 'on-the-way' && ''}
                {driverStatusPopup.status === 'arrived' && ''}
                {driverStatusPopup.status === 'pickup' && ''}
                {driverStatusPopup.status === 'drop-off' && ''}
                {driverStatusPopup.status === 'payment' && ''}
                {driverStatusPopup.status === 'completed' && ''}
              </div>

              {/* Status Message */}
              <h3 className="text-2xl font-bold text-[#121212] text-center mb-2">
                {driverStatusPopup.status === 'on-the-way' && 'Driver On The Way'}
                {driverStatusPopup.status === 'arrived' && 'Driver Arrived'}
                {driverStatusPopup.status === 'pickup' && 'Picked Up!'}
                {driverStatusPopup.status === 'drop-off' && 'Arrived at Destination'}
                {driverStatusPopup.status === 'payment' && 'Complete Payment'}
                {driverStatusPopup.status === 'completed' && 'Ride Completed!'}
              </h3>

              <p className="text-[#64748B] text-center mb-6">{driverStatusPopup.message}</p>

              {/* Status Details */}
              <div className="bg-[#F8F9FA] rounded-xl p-4 mb-6">
                <div className="flex items-center justify-between">
                  <span className="text-sm text-[#64748B]">Status Update</span>
                  <span className="font-bold text-[#121212]">
                    {driverStatusPopup.status === 'on-the-way' && 'On the way'}
                    {driverStatusPopup.status === 'arrived' && 'Arrived'}
                    {driverStatusPopup.status === 'pickup' && 'Picked up'}
                    {driverStatusPopup.status === 'drop-off' && 'At destination'}
                    {driverStatusPopup.status === 'payment' && 'Payment pending'}
                    {driverStatusPopup.status === 'completed' && 'Completed'}
                  </span>
                </div>
                <div className="flex items-center justify-between mt-3">
                  <span className="text-sm text-[#64748B]">Time</span>
                  <span className="text-sm text-[#121212]">Just now</span>
                </div>
              </div>

              <Button
                onClick={() => setDriverStatusPopup(null)}
                className="w-full bg-[#E11D48] hover:bg-[#BE123C] text-white py-3 text-lg font-bold"
              >
                OK 
              </Button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

import { useState, useEffect, useRef } from "react";
import { Search, MapPin, Users, User as UserIcon, ChevronDown, X, Clock, CreditCard, Utensils, Search as SearchIcon, User, Navigation, MessageCircle, Bike, Home as HomeIcon, ShoppingCart, ClipboardList } from "lucide-react";
import { Link } from "react-router";
import { Button } from "../ui/button";
import { Card } from "../ui/card";
import { Badge } from "../ui/badge";
import { Input } from "../ui/input";
import { GoogleMap, LoadScript, Marker, InfoWindow } from "@react-google-maps/api";
import tricycleIcon from '../../../assets/0b76d1aa56b8ad6e15dd4efc8a0100b0ca5762a1.png';
import { useAuth } from "../../contexts/AuthContext";
import { supabaseHelpers } from "@/lib/supabase";
import { supabase } from "../../../utils/supabase";
import SharedRides from "./SharedRides";
import ShareRideLobby from "./ShareRideLobby";
import BrowseAvailableLobbies from "./BrowseAvailableLobbies";

// Get Google Maps API Key from environment variable
const GOOGLE_MAPS_API_KEY = import.meta.env.VITE_GOOGLE_MAPS_API_KEY || "";

export default function CustomerHome() {
  const { user } = useAuth();
  const [selectedVehicle, setSelectedVehicle] = useState<'share' | 'special' | null>(null);
  const [currentLocation, setCurrentLocation] = useState<{ lat: number; lng: number }>({ lat: 14.5995, lng: 120.9842 }); // Default: Manila
  const [selectedMarker, setSelectedMarker] = useState<{ lat: number; lng: number } | null>(null);
  const [isLoadingLocation, setIsLoadingLocation] = useState(true);
  const [locationError, setLocationError] = useState<string | null>(null);
  const [showLocationPicker, setShowLocationPicker] = useState(false);
  const [activeLocationInput, setActiveLocationInput] = useState<'pickup' | 'dropoff' | null>(null);
  const [pickup, setPickup] = useState("");
  const [pickupAddress, setPickupAddress] = useState("");
  const [dropoff, setDropoff] = useState("");
  const [dropoffAddress, setDropoffAddress] = useState("");
  const [searchQuery, setSearchQuery] = useState("");
  const [showBookingConfirm, setShowBookingConfirm] = useState(false);
  const [showSharedRides, setShowSharedRides] = useState(false);
  const [showShareLobby, setShowShareLobby] = useState(false);
  const [paymentMethod, setPaymentMethod] = useState<'COD' | 'GCASH'>('GCASH');
  const [activeRide, setActiveRide] = useState<any>(null);
  const [rideStatus, setRideStatus] = useState<'searching' | 'driver-found' | 'picking-up' | 'in-transit' | null>(null);
  const [isSearchMinimized, setIsSearchMinimized] = useState(false);
  const [currentRequestId, setCurrentRequestId] = useState<string | null>(null);
  const [currentSharedRideId, setCurrentSharedRideId] = useState<string | null>(null);
  const [showPassengerCount, setShowPassengerCount] = useState(false);
  const [passengerCount, setPassengerCount] = useState(1);
  const [showLobbyList, setShowLobbyList] = useState(false);
  const [unreadMessagesCount, setUnreadMessagesCount] = useState(0);
  const [driverAcceptedPopup, setDriverAcceptedPopup] = useState<any>(null);
  const [driverStatusPopup, setDriverStatusPopup] = useState<{ status: string; message: string } | null>(null);
  const [showValidationError, setShowValidationError] = useState(false);
  const [showSameLocationError, setShowSameLocationError] = useState(false);
  const [rideCompletedPopup, setRideCompletedPopup] = useState(false);
  const [privateRidePrice, setPrivateRidePrice] = useState(50); // Default price for special rides
  const [sharedRidePrice, setSharedRidePrice] = useState(15); // Default price for share rides
  const unsubscribeRef = useRef<(() => void) | null>(null);

  // Get user's current location on component mount
  useEffect(() => {
    setIsLoadingLocation(true);
    setLocationError(null);

    if ('geolocation' in navigator) {
      navigator.geolocation.getCurrentPosition(
        (position) => {
          const { latitude, longitude } = position.coords;
          setCurrentLocation({ lat: latitude, lng: longitude });
          setIsLoadingLocation(false);
          console.log('User location:', latitude, longitude);
        },
        (error) => {
          console.warn('Geolocation error:', error.message);
          setLocationError(error.message);
          setIsLoadingLocation(false);
          // Keep default location (Manila) if geolocation fails
        },
        {
          enableHighAccuracy: true,
          timeout: 10000,
          maximumAge: 0
        }
      );
    } else {
      console.warn('Geolocation not supported by browser');
      setLocationError('Geolocation not supported');
      setIsLoadingLocation(false);
    }
  }, []);

  // DEBUG: Clear all ride data
  const clearAllRideData = () => {
    if (confirm('Clear all lobbies and requests? This will reset the testing environment.')) {
      localStorage.removeItem('trikeserve_share_lobbies');
      localStorage.removeItem('trikeserve_ride_requests');
      localStorage.removeItem('trikeserve_active_ride');
      localStorage.removeItem('trikeserve_accepted_rides');
      
      // Reset component state
      setShowShareLobby(false);
      setShowSharedRides(false);
      setRideStatus(null);
      setActiveRide(null);
      setPickup('');
      setDropoff('');
      setPickupAddress('');
      setDropoffAddress('');
      setSelectedVehicle(null);
      
      alert('✅ All ride data cleared! You can now create a new lobby.');
      window.location.reload();
    }
  };

  // Load persisted ride data on mount
  useEffect(() => {
    const savedRideData = localStorage.getItem('trikeserve_active_ride');
    if (savedRideData) {
      try {
        const rideData = JSON.parse(savedRideData);
        setRideStatus(rideData.status);
        setPickup(rideData.pickup);
        setPickupAddress(rideData.pickupAddress);
        setDropoff(rideData.dropoff);
        setDropoffAddress(rideData.dropoffAddress);
        setSelectedVehicle(rideData.vehicleType);
        setPaymentMethod(rideData.paymentMethod);
        setCurrentRequestId(rideData.requestId);
        if (rideData.activeRide) {
          setActiveRide(rideData.activeRide);
        }
      } catch (error) {
        console.error('Error loading ride data:', error);
      }
    }

    // Check if user is in an active lobby
    const checkActiveLobby = () => {
      if (!user?.id) return;

      const lobbiesData = localStorage.getItem('trikeserve_share_lobbies');
      if (!lobbiesData) return;

      try {
        const lobbies = JSON.parse(lobbiesData);
        // Find lobby where user is a passenger (waiting OR driver-found status)
        const userLobby = lobbies.find((lobby: any) => 
          (lobby.status === 'waiting' || lobby.status === 'driver-found') &&
          lobby.passengers.some((p: any) => 
            p.id === user.id || p.id.startsWith(`${user.id}_companion_`)
          )
        );

        if (userLobby) {
          // User is already in a lobby, restore state
          setPickup(userLobby.pickup);
          setPickupAddress(userLobby.pickupAddress);
          setDropoff(userLobby.dropoff);
          setDropoffAddress(userLobby.dropoffAddress);
          setSelectedVehicle('share');
          
          // Count how many seats the user has (main + companions)
          const userSeats = userLobby.passengers.filter((p: any) => 
            p.id === user.id || p.id.startsWith(`${user.id}_companion_`)
          ).length;
          setPassengerCount(userSeats);
          
          // Show the lobby
          setShowShareLobby(true);
          console.log('✅ Restored active lobby:', userLobby.id, 'Status:', userLobby.status);
        }
      } catch (error) {
        console.error('Error checking active lobby:', error);
      }
    };

    checkActiveLobby();
  }, [user]);

  // Load admin pricing settings from Supabase
  useEffect(() => {
    const loadPricingSettings = async () => {
      try {
        const { data, error } = await supabase
          .from('admin_settings')
          .select('setting_value')
          .eq('setting_key', 'rates')
          .single();

        if (error) {
          console.warn('Error loading pricing from Supabase:', error);
          return;
        }

        if (data?.setting_value) {
          const settings = JSON.parse(data.setting_value);
          setSharedRidePrice(settings.sharedRide || 15);
          setPrivateRidePrice(settings.privateRide || 50);
          console.log('✅ Loaded admin pricing - Shared: ₱' + settings.sharedRide + ', Private: ₱' + settings.privateRide);
        }
      } catch (error) {
        console.error('Error parsing pricing settings:', error);
      }
    };

    loadPricingSettings();
  }, []);

  // Listen for accepted rides and status updates (polling + storage events)
  useEffect(() => {
    // Continue polling as long as there's an active ride or we're searching
    if (!currentRequestId) return;

    const checkForAcceptedRide = () => {
      const acceptedRidesData = localStorage.getItem('trikeserve_accepted_rides');
      if (acceptedRidesData) {
        try {
          const acceptedRides = JSON.parse(acceptedRidesData);
          const myRide = acceptedRides.find((ride: any) => ride.id === currentRequestId);
          
          if (myRide) {
            // Driver accepted the ride!
            setActiveRide({
              driver: myRide.driverName || 'Driver',
              plateNumber: myRide.driverPlate || 'N/A',
              rating: myRide.driverRating || '4.8',
              eta: myRide.eta || '5 mins',
            });

            // ❌ REMOVED: Popup will be shown from real-time subscription instead
            // This prevents duplicate popups from multiple triggers

            setRideStatus('driver-found');
            setIsSearchMinimized(false);
          }
        } catch (error) {
          console.error('Error checking accepted rides:', error);
        }
      }
    };

    // Check for driver status updates (all ride types)
    const checkForDriverStatusUpdate = async () => {
      if (!currentRequestId) {
        console.log('❌ No currentRequestId, skipping driver status check');
        return;
      }

      // Query database directly for driver status (Option 2 - Database-Driven)
      try {
        const { data: rideRequest, error } = await supabaseHelpers.getRideRequest(currentRequestId);

        console.log(' CHECKING DATABASE for Ride Status Update:');
        console.log('   Request ID:', currentRequestId);
        console.log('   DB Driver Status:', rideRequest?.driver_status);
        console.log('   DB Accepted Driver ID:', rideRequest?.accepted_driver_id);
        console.log('   Status Message:', rideRequest?.driver_status_message);

        if (error) {
          console.error('❌ Database error:', error);
          return;
        }

        if (!rideRequest) {
          console.log('❌ Ride request not found in database');
          return;
        }

      // CRITICAL: Check if driver has been accepted (this means driver info card should show)
        if (rideRequest.accepted_driver_id && !activeRide) {
          console.log('✅ DRIVER ACCEPTED (Polling detected):', rideRequest.accepted_driver_id);
          console.log('   Driver Name:', rideRequest.driver_name);
          console.log('   Driver Plate:', rideRequest.driver_plate);
          console.log('   Driver Rating:', rideRequest.driver_rating);
          console.log('   Setting activeRide and rideStatus = driver-found');

          const newActiveRide = {
            driver: rideRequest.driver_name || 'Driver',
            plateNumber: rideRequest.driver_plate || 'N/A',
            rating: rideRequest.driver_rating || '4.8',
            eta: rideRequest.eta || '5 mins',
          };

          console.log(' Active Ride Object:', newActiveRide);

          setActiveRide(newActiveRide);
          setRideStatus('driver-found');

          console.log('✅ STATE UPDATED: rideStatus should now be "driver-found"');

          // ❌ REMOVED: Popup will be shown from real-time subscription instead
          // This prevents duplicate popups from multiple triggers
        }

        // Only show status popup if driver_status has been updated AND we haven't shown it yet
        if (rideRequest.driver_status && rideRequest.driver_status !== 'pending') {
          const lastShownStatusKey = `last_shown_status_${currentRequestId}`;
          const lastShownStatus = localStorage.getItem(lastShownStatusKey);

          // Check if this is a new status update
          if (rideRequest.driver_status !== lastShownStatus) {
            console.log('✅ NEW STATUS UPDATE FROM DATABASE:', rideRequest.driver_status);

            // Map database status to popup display
            const statusDisplayMap: { [key: string]: string } = {
              'on-the-way': 'Your driver is on the way to pick you up! ',
              'arrived': 'Your driver has arrived! ',
              'in-progress': 'Your ride is in progress!',
              'completed': 'Your ride has been completed! Thank you for using TrikeServe. '
            };

            setDriverStatusPopup({
              status: rideRequest.driver_status,
              message: statusDisplayMap[rideRequest.driver_status] || rideRequest.driver_status_message || 'Ride status updated',
              timestamp: Date.now()
            });

            // Store that we showed this status
            localStorage.setItem(lastShownStatusKey, rideRequest.driver_status);

            // If ride is completed, clear everything after showing popup
            if (rideRequest.driver_status === 'completed') {
              console.log(' RIDE COMPLETED! Showing completion popup...');
              setRideCompletedPopup(true);
              setTimeout(() => {
                // Clear all ride data
                setRideStatus(null);
                setActiveRide(null);
                setCurrentRequestId(null);
                setPickup('');
                setDropoff('');
                setPickupAddress('');
                setDropoffAddress('');
                setSelectedVehicle(null);
                setDriverStatusPopup(null);

                // Clear from localStorage
                localStorage.removeItem('trikeserve_active_ride');
                localStorage.removeItem(lastShownStatusKey);
              }, 4000);
            } else {
              // Auto-dismiss after 4 seconds for other statuses
              setTimeout(() => {
                setDriverStatusPopup(null);
              }, 4000);
            }
          }
        }
      } catch (error) {
        console.error('❌ Error checking driver status from database:', error);
      }
    };

    // Check immediately
    checkForAcceptedRide();
    checkForDriverStatusUpdate();

    // Poll every 2 seconds
    const interval = setInterval(() => {
      checkForAcceptedRide();
      checkForDriverStatusUpdate();
    }, 2000);

    // Listen for storage events (cross-tab sync AND same-tab events)
    const handleStorageChange = (e: StorageEvent) => {
      console.log(' Storage Event Received:', e.key);
      if (e.key === 'trikeserve_accepted_rides') {
        console.log(' Accepted rides changed, checking...');
        checkForAcceptedRide();
      }
      if (e.key?.startsWith('driver_status_')) {
        console.log(' Driver status changed, checking...', e.key);
        checkForDriverStatusUpdate();
      }
    };

    // Also listen for custom events dispatched by driver
    const handleCustomStorageEvent = (e: any) => {
      console.log(' Custom Storage Event:', e.detail?.key);
      if (e.detail?.key?.startsWith('driver_status_')) {
        checkForDriverStatusUpdate();
      }
    };

    window.addEventListener('storage', handleStorageChange);
    window.addEventListener('custom-storage-change', handleCustomStorageEvent);

    return () => {
      clearInterval(interval);
      window.removeEventListener('storage', handleStorageChange);
      window.removeEventListener('custom-storage-change', handleCustomStorageEvent);
    };
  }, [rideStatus, currentRequestId, selectedVehicle]);

  // Real-time database subscriptions for driver updates
  useEffect(() => {
    if (!currentRequestId || !user?.id) return;

    console.log(' Setting up real-time database subscriptions for ride:', currentRequestId);

    // Subscribe to ride updates (driver status, acceptance, completion)
    const unsubscribe = supabaseHelpers.subscribeToRideUpdates(currentRequestId, (updatedRide) => {
      console.log(' Real-time ride update received:', updatedRide);

      // DEBUG: Log all driver-related fields
      console.log(' DRIVER INFO FROM DATABASE:');
      console.log('   accepted_driver_id:', updatedRide.accepted_driver_id);
      console.log('   driver_name:', updatedRide.driver_name);
      console.log('   driver_plate:', updatedRide.driver_plate);
      console.log('   driver_rating:', updatedRide.driver_rating);
      console.log('   driver_photo:', updatedRide.driver_photo);
      console.log('   status:', updatedRide.status);

      // Check if driver was accepted - THIS IS THE KEY!
      if (updatedRide.accepted_driver_id && !activeRide) {
        console.log('✅ DRIVER ACCEPTED (Real-time):', updatedRide.accepted_driver_id);

        const rideState = {
          driver: updatedRide.driver_name || 'Driver',
          plateNumber: updatedRide.driver_plate || 'N/A',
          rating: updatedRide.driver_rating || '4.8',
          eta: updatedRide.eta || '5 mins',
        };

        console.log(' Setting activeRide state with:', rideState);
        console.log(' Setting rideStatus to: driver-found');

        setActiveRide(rideState);
        setRideStatus('driver-found');  // ← CRITICAL! This makes the card appear!

        // Show acceptance popup
        setDriverAcceptedPopup({
          driverName: updatedRide.driver_name || 'Driver',
          driverPlate: updatedRide.driver_plate || 'N/A',
          driverRating: updatedRide.driver_rating || '4.8',
          driverPhoto: '‍✈️',
        });
      }

      // Check if ride was completed
      if (updatedRide.driver_status === 'completed') {
        console.log(' RIDE COMPLETED (Real-time):', updatedRide);
        setRideCompletedPopup(true);

        setTimeout(() => {
          setRideStatus(null);
          setActiveRide(null);
          setCurrentRequestId(null);
          setPickup('');
          setDropoff('');
          setPickupAddress('');
          setDropoffAddress('');
          setSelectedVehicle(null);
        }, 4000);
      }

      // Check for other driver status updates (for popup messages)
      if (updatedRide.driver_status && updatedRide.driver_status !== 'pending') {
        const statusDisplayMap: { [key: string]: string } = {
          'on-the-way': 'Your driver is on the way to pick you up! ',
          'arrived': 'Your driver has arrived! ',
          'in-progress': 'Your ride is in progress!',
          'completed': 'Your ride has been completed! Thank you for using TrikeServe. '
        };

        setDriverStatusPopup({
          status: updatedRide.driver_status,
          message: statusDisplayMap[updatedRide.driver_status] || updatedRide.driver_status_message || 'Ride status updated',
          timestamp: Date.now()
        });

        // Auto-dismiss after 4 seconds
        setTimeout(() => {
          setDriverStatusPopup(null);
        }, 4000);
      }
    });

    // Save unsubscribe function
    unsubscribeRef.current = unsubscribe;

    return () => {
      if (unsubscribeRef.current) {
        console.log(' Cleaning up real-time subscription');
        unsubscribeRef.current();
      }
    };
  }, [currentRequestId, user?.id]);

  // Persist ride data whenever it changes
  useEffect(() => {
    if (rideStatus) {
      const rideData = {
        status: rideStatus,
        pickup,
        pickupAddress,
        dropoff,
        dropoffAddress,
        vehicleType: selectedVehicle,
        paymentMethod,
        activeRide,
        requestId: currentRequestId,
      };
      localStorage.setItem('trikeserve_active_ride', JSON.stringify(rideData));
    } else {
      localStorage.removeItem('trikeserve_active_ride');
    }
  }, [rideStatus, pickup, pickupAddress, dropoff, dropoffAddress, selectedVehicle, paymentMethod, activeRide, currentRequestId]);

  // Count unread messages from drivers
  useEffect(() => {
    const countUnreadMessages = () => {
      if (!user?.id) return;
      
      let unreadCount = 0;
      
      // Scan localStorage for all chat keys
      for (let i = 0; i < localStorage.length; i++) {
        const key = localStorage.key(i);
        if (key && key.startsWith('chat_')) {
          try {
            const messages = JSON.parse(localStorage.getItem(key) || '[]');
            // Count unread messages from drivers (sent by riders)
            const unread = messages.filter((m: any) => 
              m.senderType === 'driver' && !m.read
            ).length;
            unreadCount += unread;
          } catch (error) {
            console.error('Error counting unread messages:', error);
          }
        }
      }
      
      setUnreadMessagesCount(unreadCount);
    };

    // Count initially
    countUnreadMessages();

    // Poll for updates every 2 seconds
    const interval = setInterval(countUnreadMessages, 2000);

    // Listen for storage events (cross-tab sync)
    const handleStorageChange = (e: StorageEvent) => {
      if (e.key?.startsWith('chat_')) {
        countUnreadMessages();
      }
    };

    window.addEventListener('storage', handleStorageChange);

    return () => {
      clearInterval(interval);
      window.removeEventListener('storage', handleStorageChange);
    };
  }, [user]);

  const popularLocations = [
    { name: "Adelfa Street", address: "Adelfa Street, Valenzuela", icon: "" },
    { name: "B.Garcia Street", address: "B.Garcia Street, Valenzuela", icon: "" },
    { name: "Cadena de Amor Street", address: "Cadena de Amor Street, Valenzuela", icon: "" },
    { name: "Carnation Street", address: "Carnation Street, Valenzuela", icon: "" },
    { name: "Daffodil Street", address: "Daffodil Street, Valenzuela", icon: "" },
    { name: "Dama de Noche Street", address: "Dama de Noche Street, Valenzuela", icon: "" },
    { name: "Gladiola Street", address: "Gladiola Street, Valenzuela", icon: "" },
    { name: "Ilang-Ilang Street", address: "Ilang-Ilang Street, Valenzuela", icon: "" },
    { name: "Lilac Street", address: "Lilac Street, Valenzuela", icon: "" },
    { name: "Jasmin Street", address: "Jasmin Street, Valenzuela", icon: "" },
    { name: "Morning Glory Street", address: "Morning Glory Street, Valenzuela", icon: "" },
    { name: "Marigold Street", address: "Marigold Street, Valenzuela", icon: "" },
    { name: "Orchid Street", address: "Orchid Street, Valenzuela", icon: "" },
    { name: "Rosal Street", address: "Rosal Street, Valenzuela", icon: "" },
    { name: "Balikatan Street", address: "Balikatan Street, Valenzuela", icon: "" },
    { name: "Rose Mary Street", address: "Rose Mary Street, Valenzuela", icon: "" },
    { name: "Sampaguita Street", address: "Sampaguita Street, Valenzuela", icon: "" },
    { name: "Everlasting Street", address: "Everlasting Street, Valenzuela", icon: "" },
    { name: "Tagalag Terminal", address: "Main Road, Tagalag", icon: "" },
    { name: "Barangay Hall", address: "Tagalag Center", icon: "️" },
    { name: "Tagalag Market", address: "Market District", icon: "" },
  ];

  const handleLocationSelect = (location: any) => {
    if (activeLocationInput === 'pickup') {
      setPickup(location.name);
      setPickupAddress(location.address);
    } else if (activeLocationInput === 'dropoff') {
      setDropoff(location.name);
      setDropoffAddress(location.address);
    }
    setShowLocationPicker(false);
    setActiveLocationInput(null);
    setSearchQuery("");
  };

  const handleBookRide = async () => {
    if (!selectedVehicle) return;
    
    // Validate pickup and dropoff locations
    if (!pickup.trim() || !dropoff.trim()) {
      setShowValidationError(true);
      return;
    }

    // Validate that pickup and dropoff are not the same (for special rides)
    if (selectedVehicle === 'special') {
      if (pickup.trim().toLowerCase() === dropoff.trim().toLowerCase()) {
        setShowSameLocationError(true);
        return;
      }
    }

    if (selectedVehicle === 'share' && user?.id) {
      try {
        const { data: waitingLobbies, error } = await supabaseHelpers.getAvailableLobbies();
        if (!error && waitingLobbies) {
          const existingLobby = waitingLobbies.find((lobby: any) => {
            const passengers = Array.isArray(lobby.passengers_json) ? lobby.passengers_json : [];
            return passengers.some((p: any) => p.id === user.id || p.id.startsWith(`${user.id}_companion_`));
          });

          if (existingLobby) {
            alert('You are already in an active lobby. Please leave your current lobby before joining another.');
            setShowShareLobby(true);
            return;
          }
        }
      } catch (error) {
        console.error('Error checking active lobbies:', error);
      }
    }
    
    // Ask for passenger count for both share and special rides
    setShowPassengerCount(true);
  };

  const handleConfirmBooking = async () => {
    setShowBookingConfirm(false);
    
    // For share rides, open the lobby system
    if (selectedVehicle === 'share') {
      setShowShareLobby(true);
    } else {
      // For special rides, save to Supabase database
      setRideStatus('searching');
      
      try {
        // Validate user is authenticated
        if (!user?.id) {
          console.error('❌ User ID not found');
          alert('❌ Error: User not authenticated. Please log in again.');
          setRideStatus(null);
          return;
        }

        console.log(' Booking ride for user:', user.id);

        // Create ride request data in correct database format
        const rideRequest = {
          customer_id: user.id,
          pickup_location: pickup,
          dropoff_location: dropoff,
          status: 'pending',
          ride_type: 'special',
          payment_method: paymentMethod === 'GCASH' ? 'GCASH' : 'COD',
          amount: getPrice(),
          passenger_count: passengerCount,
          created_at: new Date().toISOString(),
          updated_at: new Date().toISOString(),
        };

        console.log(' Sending request to Supabase:', rideRequest);

        // Save to Supabase database
        const { data: savedRequest, error: dbError } = await supabaseHelpers.createRideRequest(rideRequest);

        console.log(' Supabase response:', { data: savedRequest, error: dbError });

        if (dbError) {
          console.error('❌ Database error:', dbError);
          console.error('❌ Error code:', dbError.code);
          console.error('❌ Error message:', dbError.message);
          alert(`❌ Error booking ride: ${dbError.message || 'Please try again.'}`);
          setRideStatus(null);
          return;
        }

        if (savedRequest) {
          setCurrentRequestId(savedRequest.id);
          console.log('✅ Ride request saved to database:', savedRequest);
          console.log(' Request ID:', savedRequest.id);
          console.log('️ Saved in Supabase ride_requests table');
        } else {
          console.error('❌ No data returned from database');
          alert('❌ Error: No response from database. Please try again.');
          setRideStatus(null);
        }
      } catch (error: any) {
        console.error('❌ Error creating ride request:', error);
        console.error('❌ Error stack:', error.stack);
        console.error('❌ Error message:', error.message);
        alert(`❌ Error booking ride: ${error.message || 'Please try again.'}`);
        setRideStatus(null);
      }
    }
  };

  const handleCancelRide = () => {
    setActiveRide(null);
    setRideStatus(null);
    setCurrentRequestId(null);
  };

  const getPrice = () => {
    if (selectedVehicle === 'share') return sharedRidePrice;
    if (selectedVehicle === 'special') return privateRidePrice;
    return 0;
  };

  const filteredLocations = popularLocations.filter(loc =>
    loc.name.toLowerCase().includes(searchQuery.toLowerCase()) ||
    loc.address.toLowerCase().includes(searchQuery.toLowerCase())
  );

  return (
    <div className="min-h-screen bg-white flex flex-col relative">
      {/* Full Screen Map */}
      <div className="absolute inset-0">
        {!GOOGLE_MAPS_API_KEY ? (
          <div className="w-full h-full flex items-center justify-center bg-gray-200">
            <div className="text-center">
              <p className="text-xl font-bold text-red-600 mb-4">⚠️ Google Maps API Key Missing</p>
              <p className="text-gray-700 mb-4">To use Google Maps, please add your API key to .env.local</p>
            </div>
          </div>
        ) : (
          <LoadScript googleMapsApiKey={GOOGLE_MAPS_API_KEY} libraries={["places"]}>
            <GoogleMap
              mapContainerStyle={{ width: "100%", height: "100%" }}
              center={currentLocation}
              zoom={15}
              options={{
                zoomControl: false,
                fullscreenControl: true,
                streetViewControl: false,
                mapTypeControl: true,
              }}
            >
              {/* Current Location Marker */}
              <Marker
                position={currentLocation}
                onClick={() => setSelectedMarker(currentLocation)}
                title="Your location"
              />

              {/* Info Window for selected marker */}
              {selectedMarker && (
                <InfoWindow
                  position={selectedMarker}
                  onCloseClick={() => setSelectedMarker(null)}
                >
                  <div className="text-sm">
                    <p className="font-bold">Your current location</p>
                    <p className="text-gray-600">
                      {selectedMarker.lat.toFixed(4)}, {selectedMarker.lng.toFixed(4)}
                    </p>
                  </div>
                </InfoWindow>
              )}
            </GoogleMap>
          </LoadScript>
        )}

        {/* Search Bar Overlay */}
        <div className="absolute top-4 left-4 right-4 z-[1000]">
          <div className="flex items-center gap-2">
            <div className="relative flex-1">
              <Search className="absolute left-4 top-1/2 -translate-y-1/2 w-5 h-5 text-[#94A3B8]" />
              <input
                type="text"
                placeholder="Search"
                className="w-full pl-12 pr-4 py-3.5 bg-white rounded-xl shadow-lg border-0 text-base"
                style={{ outline: 'none' }}
              />
            </div>
          </div>
        </div>

        {/* Bottom Sheet - Main Booking Interface */}
        {!activeRide && (
          <div className="absolute bottom-20 left-0 right-0 z-[999] px-4">
            <Card className="bg-white shadow-2xl rounded-t-3xl">
              <div className="px-5 pb-6 pt-6">
                {/* Vehicle Type Selection */}
                <div className="grid grid-cols-2 gap-4 mb-6">
                  {/* Share Ride */}
                  <button
                    onClick={() => setSelectedVehicle('share')}
                    className={`p-3 rounded-2xl border-2 transition-all ${
                      selectedVehicle === 'share'
                        ? 'border-[#E11D48] bg-[#FFF1F2]'
                        : 'border-[#E2E8F0] bg-white'
                    }`}
                  >
                    <div className="flex flex-col items-center gap-2">
                      <div className="w-20 h-20 rounded-2xl bg-white border-2 border-[#E2E8F0] flex items-center justify-center">
                        <Users className="w-10 h-10 text-[#121212]" />
                      </div>
                      <span className="font-bold text-sm text-[#121212]">Share Ride</span>
                    </div>
                  </button>

                  {/* Special Ride */}
                  <button
                    onClick={() => setSelectedVehicle('special')}
                    className={`p-3 rounded-2xl border-2 transition-all ${
                      selectedVehicle === 'special'
                        ? 'border-[#E11D48] bg-[#FFF1F2]'
                        : 'border-[#E2E8F0] bg-white'
                    }`}
                  >
                    <div className="flex flex-col items-center gap-2">
                      <div className="w-20 h-20 rounded-2xl bg-white border-2 border-[#E2E8F0] flex items-center justify-center">
                        <UserIcon className="w-10 h-10 text-[#121212]" />
                      </div>
                      <span className="font-bold text-sm text-[#121212]">Special Ride</span>
                    </div>
                  </button>
                </div>

                {/* Location Inputs */}
                <div className="space-y-3 mb-4">
                  {/* Pick up Location Label */}
                  <label className="text-xs font-semibold text-[#64748B] uppercase tracking-wide block mb-2">
                    Pick up location
                  </label>
                  
                  {/* Current Location */}
                  <Card 
                    className="p-3 border-2 border-[#E2E8F0] shadow-sm cursor-pointer hover:border-[#E11D48] transition-colors"
                    onClick={() => {
                      setActiveLocationInput('pickup');
                      setShowLocationPicker(true);
                    }}
                  >
                    <div className="flex items-start gap-3">
                      <div className="mt-0.5">
                        <MapPin className="w-4 h-4 text-[#121212]" />
                      </div>
                      <div className="flex-1 min-w-0">
                        <p className="font-bold text-sm text-[#121212] mb-0.5">{pickup}</p>
                        <p className="text-xs text-[#64748B] truncate">{pickupAddress}</p>
                      </div>
                      <button className="mt-0.5 flex-shrink-0">
                        <ChevronDown className="w-4 h-4 text-[#64748B]" />
                      </button>
                    </div>
                  </Card>

                  {/* Drop off Location Label */}
                  <label className="text-xs font-semibold text-[#64748B] uppercase tracking-wide block mb-2 mt-4">
                    Drop off location
                  </label>

                  {/* Destination */}
                  <Card 
                    className="p-3 border-2 border-[#E2E8F0] shadow-sm cursor-pointer hover:border-[#E11D48] transition-colors"
                    onClick={() => {
                      setActiveLocationInput('dropoff');
                      setShowLocationPicker(true);
                    }}
                  >
                    <div className="flex items-start gap-3">
                      <div className="mt-0.5">
                        <MapPin className="w-4 h-4 text-[#E11D48]" />
                      </div>
                      <div className="flex-1 min-w-0">
                        <p className="font-bold text-sm text-[#121212] mb-0.5">{dropoff}</p>
                        <p className="text-xs text-[#64748B] truncate">{dropoffAddress}</p>
                      </div>
                      <button className="mt-0.5 flex-shrink-0">
                        <ChevronDown className="w-4 h-4 text-[#64748B]" />
                      </button>
                    </div>
                  </Card>
                </div>

                {/* Book Ride Button */}
                {selectedVehicle && (
                  <Button 
                    onClick={handleBookRide}
                    className="w-full bg-[#E11D48] hover:bg-[#BE123C] text-white py-6 text-lg font-bold uppercase rounded-xl"
                  >
                    Book {selectedVehicle === 'share' ? 'Share' : 'Special'} Ride - ₱{getPrice()}
                  </Button>
                )}
              </div>
            </Card>
          </div>
        )}


        {/* Active Ride Card - Driver Info - ONLY when rideStatus === 'driver-found' AND activeRide exists */}
        {rideStatus === 'driver-found' && activeRide && (
          <div className="absolute bottom-20 left-0 right-0 z-[1100] p-4">
            <Card className="bg-white shadow-2xl border-2 border-[#E11D48] p-6">
              {/* Driver Info */}
              <div className="flex items-center gap-4 mb-4">
                <div className="w-16 h-16 bg-[#FFF1F2] rounded-full flex items-center justify-center">
                  <span className="text-3xl">‍✈️</span>
                </div>
                <div className="flex-1">
                  <h3 className="font-bold text-lg text-[#121212]">{activeRide.driver}</h3>
                  <div className="flex items-center gap-2">
                    <Badge className="bg-green-500 text-white">Driver Found</Badge>
                    <span className="text-sm text-[#64748B]">{activeRide.plateNumber}</span>
                  </div>
                </div>
                <div className="text-right">
                  <div className="flex items-center gap-1 text-yellow-500 mb-1">
                    <span className="text-lg">⭐</span>
                    <span className="font-bold text-[#121212]">{activeRide.rating}</span>
                  </div>
                  <p className="text-sm text-[#64748B]">ETA: {activeRide.eta}</p>
                </div>
              </div>

              {/* Trip Info */}
              <div className="bg-[#F8F9FA] rounded-xl p-4 mb-4 space-y-2">
                <div className="flex items-start gap-2">
                  <MapPin className="w-4 h-4 text-[#121212] mt-0.5" />
                  <div className="flex-1">
                    <p className="text-xs text-[#64748B]">Pickup</p>
                    <p className="font-semibold text-sm text-[#121212]">{pickup}</p>
                  </div>
                </div>
                <div className="flex items-start gap-2">
                  <MapPin className="w-4 h-4 text-[#E11D48] mt-0.5" />
                  <div className="flex-1">
                    <p className="text-xs text-[#64748B]">Drop-off</p>
                    <p className="font-semibold text-sm text-[#121212]">{dropoff}</p>
                  </div>
                </div>
              </div>

              {/* Payment */}
              <div className="flex items-center justify-between mb-4">
                <span className="text-[#64748B]">Payment ({paymentMethod})</span>
                <span className="text-2xl font-bold text-[#E11D48]">₱{getPrice()}</span>
              </div>

              {/* Actions */}
              <div className="grid grid-cols-2 gap-3">
                <Button
                  variant="outline"
                  className="flex items-center gap-2"
                >
                  <MessageCircle className="w-4 h-4" />
                  Message
                </Button>
                <Button
                  onClick={handleCancelRide}
                  variant="outline"
                  className="text-red-600 border-red-300 hover:bg-red-50"
                >
                  Cancel Ride
                </Button>
              </div>
            </Card>
          </div>
        )}

        {/* Validation Error Popup */}
        {showValidationError && (
          <div className="fixed inset-0 bg-black/50 z-[2100] flex items-center justify-center p-4">
            <Card className="bg-white p-8 max-w-sm w-full text-center animate-infinite-bounce">
              <div className="w-20 h-20 bg-red-100 rounded-full flex items-center justify-center mx-auto mb-4">
                <span className="text-4xl">⚠️</span>
              </div>
              <h3 className="text-xl font-bold text-red-600 mb-2">Incomplete Information</h3>
              <p className="text-sm text-[#64748B] mb-6">
                Please complete entering your <strong>pickup location</strong> and <strong>drop-off point</strong> to proceed with booking your ride.
              </p>

              <Button
                onClick={() => setShowValidationError(false)}
                className="w-full bg-red-500 hover:bg-red-600 text-white py-3 font-bold"
              >
                Understood
              </Button>
            </Card>
          </div>
        )}

        {/* Same Location Error Popup */}
        {showSameLocationError && (
          <div className="fixed inset-0 bg-black/50 z-[2100] flex items-center justify-center p-4">
            <Card className="bg-white p-8 max-w-sm w-full text-center animate-infinite-bounce">
              <div className="w-20 h-20 bg-red-100 rounded-full flex items-center justify-center mx-auto mb-4">
                <span className="text-4xl">⚠️</span>
              </div>
              <h3 className="text-xl font-bold text-red-600 mb-2">Invalid Route</h3>
              <p className="text-sm text-[#64748B] mb-6">
                Your <strong>pickup location</strong> and <strong>drop-off point</strong> cannot be the same. Please select different locations.
              </p>

              <Button
                onClick={() => setShowSameLocationError(false)}
                className="w-full bg-red-500 hover:bg-red-600 text-white py-3 font-bold"
              >
                Understood
              </Button>
            </Card>
          </div>
        )}


        {/* Ride Completed Popup */}
        {rideCompletedPopup && (
          <div className="fixed inset-0 bg-black/50 z-[2100] flex items-center justify-center p-4">
            <Card className="bg-white p-8 max-w-sm w-full text-center animate-infinite-bounce">
              <div className="w-20 h-20 bg-blue-100 rounded-full flex items-center justify-center mx-auto mb-4">
                <span className="text-4xl"></span>
              </div>
              <h3 className="text-xl font-bold text-[#121212] mb-2">Ride Completed!</h3>
              <p className="text-sm text-[#64748B] mb-6">
                Thank you for using TrikeServe. We hope you had a great ride!
              </p>

              <Button
                onClick={() => {
                  setRideCompletedPopup(false);
                  // Reset ride state
                  setActiveRide(null);
                  setRideStatus(null);
                  setCurrentRequestId(null);
                }}
                className="w-full bg-blue-500 hover:bg-blue-600 text-white py-3 font-bold"
              >
                Done
              </Button>
            </Card>
          </div>
        )}

        {/* Driver Accepted Popup */}
        {driverAcceptedPopup && (
          <div className="fixed inset-0 bg-black/50 z-[2100] flex items-center justify-center p-4">
            <Card className="bg-white p-8 max-w-sm w-full text-center animate-infinite-bounce">
              <div className="w-24 h-24 bg-green-50 rounded-full flex items-center justify-center mx-auto mb-4">
                <span className="text-5xl">{driverAcceptedPopup.driverPhoto}</span>
              </div>
              <h3 className="text-2xl font-bold text-[#121212] mb-2"> Driver Accepted!</h3>
              <p className="text-lg font-semibold text-green-600 mb-4">{driverAcceptedPopup.driverName}</p>

              <div className="bg-[#F8F9FA] rounded-lg p-4 mb-4 space-y-2 text-left">
                <div className="flex items-center justify-between">
                  <span className="text-[#64748B]">Vehicle:</span>
                  <span className="font-semibold text-[#121212]">{driverAcceptedPopup.driverPlate}</span>
                </div>
                <div className="flex items-center justify-between">
                  <span className="text-[#64748B]">Rating:</span>
                  <div className="flex items-center gap-1">
                    <span className="text-yellow-500">⭐</span>
                    <span className="font-semibold text-[#121212]">{driverAcceptedPopup.driverRating}</span>
                  </div>
                </div>
              </div>

              <Button
                onClick={() => setDriverAcceptedPopup(null)}
                className="w-full bg-green-500 hover:bg-green-600 text-white py-3 font-bold"
              >
                Got It!
              </Button>
            </Card>
          </div>
        )}

        {/* Driver Status Update Popup */}
        {/* ❌ REMOVED: Driver status popup that appeared at top of screen */}
        {/* This was showing status updates like "On the Way", "Arrived", etc. */}
      </div>

      {/* Bottom Navigation */}
      <div className="fixed bottom-0 left-0 right-0 bg-white border-t-2 border-[#E2E8F0] px-4 py-3 z-[1500]">
        <div className="max-w-6xl mx-auto grid grid-cols-5 gap-2">
          <Link to="/customer/food" className="flex flex-col items-center gap-1">
            <HomeIcon className="w-6 h-6 text-[#64748B]" />
            <span className="text-xs text-[#64748B]">Home</span>
          </Link>
          <Link to="/customer/cart" className="flex flex-col items-center gap-1">
            <ShoppingCart className="w-6 h-6 text-[#64748B]" />
            <span className="text-xs text-[#64748B]">Cart</span>
          </Link>
          <Link to="/customer/messages" className="flex flex-col items-center gap-1 relative">
            <MessageCircle className="w-6 h-6 text-[#64748B]" />
            <span className="text-xs text-[#64748B]">Messages</span>
            {unreadMessagesCount > 0 && (
              <div className="absolute -top-1 -right-1 w-5 h-5 bg-[#E11D48] rounded-full border-2 border-white flex items-center justify-center">
                <span className="text-[10px] font-bold text-white">{unreadMessagesCount}</span>
              </div>
            )}
          </Link>
          <Link to="/customer/activity" className="flex flex-col items-center gap-1">
            <ClipboardList className="w-6 h-6 text-[#64748B]" />
            <span className="text-xs text-[#64748B]">Activity</span>
          </Link>
          <Link to="/customer/account" className="flex flex-col items-center gap-1">
            <User className="w-6 h-6 text-[#64748B]" />
            <span className="text-xs text-[#64748B]">Account</span>
          </Link>
        </div>
      </div>

      {/* Location Picker Modal */}
      {showLocationPicker && (
        <div className="fixed inset-0 bg-black/50 z-[2000] flex items-end">
          <div className="bg-white w-full rounded-t-3xl max-h-[80vh] overflow-hidden flex flex-col">
            {/* Header */}
            <div className="p-5 border-b border-[#E2E8F0]">
              <div className="flex items-center justify-between mb-4">
                <h2 className="text-xl font-bold text-[#121212]">
                  {activeLocationInput === 'pickup' ? 'Pickup Location' : 'Drop-off Location'}
                </h2>
                <button onClick={() => {
                  setShowLocationPicker(false);
                  setActiveLocationInput(null);
                  setSearchQuery("");
                }}>
                  <X className="w-6 h-6 text-[#64748B]" />
                </button>
              </div>
              <Input
                placeholder="Search location..."
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
                className="w-full"
                autoFocus
              />
            </div>

            {/* Location List */}
            <div className="flex-1 overflow-y-auto p-5 space-y-2">
              {filteredLocations.map((location, idx) => (
                <button
                  key={idx}
                  onClick={() => handleLocationSelect(location)}
                  className="w-full text-left p-4 border-2 border-[#E2E8F0] rounded-xl hover:border-[#E11D48] transition-colors"
                >
                  <div className="flex items-center gap-3">
                    <span className="text-3xl">{location.icon}</span>
                    <div className="flex-1">
                      <p className="font-bold text-[#121212]">{location.name}</p>
                      <p className="text-sm text-[#64748B]">{location.address}</p>
                    </div>
                  </div>
                </button>
              ))}
            </div>
          </div>
        </div>
      )}

      {/* Passenger Count Modal (for Share Rides) */}
      {showPassengerCount && (
        <div className="fixed inset-0 bg-black/50 z-[2000] flex items-end">
          <div className="bg-white w-full rounded-t-3xl p-6">
            <h2 className="text-2xl font-bold text-[#121212] mb-2">How many passengers?</h2>
            <p className="text-sm text-[#64748B] mb-6">Select the number of seats you need for this trip.</p>

            {/* Passenger Count Selection */}
            <div className={`grid gap-3 mb-6 ${selectedVehicle === 'special' ? 'grid-cols-2' : 'grid-cols-3'}`}>
              {selectedVehicle === 'special'
                ? [1, 2].map(count => (
                    <button
                      key={count}
                      onClick={() => setPassengerCount(count)}
                      className={`p-6 border-2 rounded-2xl transition-all ${
                        passengerCount === count
                          ? 'border-[#E11D48] bg-[#FFF1F2]'
                          : 'border-[#E2E8F0] bg-white'
                      }`}
                    >
                      <div className="flex flex-col items-center gap-2">
                        <div className="flex items-center gap-1">
                          {Array.from({ length: count }).map((_, i) => (
                            <span key={i} className="text-2xl"></span>
                          ))}
                        </div>
                        <span className="font-bold text-lg text-[#121212]">{count}</span>
                        <span className="text-xs text-[#64748B]">
                          {count === 1 ? 'passenger' : 'passengers'}
                        </span>
                      </div>
                    </button>
                  ))
                : [1, 2, 3].map(count => (
                    <button
                      key={count}
                      onClick={() => setPassengerCount(count)}
                      className={`p-6 border-2 rounded-2xl transition-all ${
                        passengerCount === count
                          ? 'border-[#E11D48] bg-[#FFF1F2]'
                          : 'border-[#E2E8F0] bg-white'
                      }`}
                    >
                      <div className="flex flex-col items-center gap-2">
                        <div className="flex items-center gap-1">
                          {Array.from({ length: count }).map((_, i) => (
                            <span key={i} className="text-2xl"></span>
                          ))}
                        </div>
                        <span className="font-bold text-lg text-[#121212]">{count}</span>
                        <span className="text-xs text-[#64748B]">
                          {count === 1 ? 'passenger' : 'passengers'}
                        </span>
                      </div>
                    </button>
                  ))
              }
            </div>

            {/* Price Info */}
            <div className="bg-[#FFF7ED] border-2 border-[#FED7AA] rounded-xl p-4 mb-6">
              <div className="flex items-center justify-between">
                <div>
                  <p className="text-xs text-[#92400E] uppercase tracking-wide font-semibold">Your Total Fare</p>
                  {selectedVehicle === 'share' ? (
                    <>
                      <p className="text-sm text-[#78350F] mt-0.5">
                        ₱{sharedRidePrice} × {passengerCount} {passengerCount === 1 ? 'seat' : 'seats'}
                      </p>
                      <p className="text-3xl font-bold text-[#EA580C]">₱{sharedRidePrice * passengerCount}</p>
                    </>
                  ) : (
                    <>
                      <p className="text-sm text-[#78350F] mt-0.5">
                        ₱{privateRidePrice} × {passengerCount} {passengerCount === 1 ? 'seat' : 'seats'}
                      </p>
                      <p className="text-3xl font-bold text-[#EA580C]">₱{privateRidePrice * passengerCount}</p>
                    </>
                  )}
                </div>
              </div>
            </div>

            {/* Info Card - Only show for Share Rides */}
            {selectedVehicle !== 'special' && (
              <div className="bg-blue-50 border border-blue-200 rounded-lg p-3 mb-6">
                <p className="text-xs text-blue-900">
                   <span className="font-semibold">Tip:</span> You'll join a shared lobby and wait for other passengers heading the same route. More passengers = faster match!
                </p>
              </div>
            )}

            {/* Action Buttons */}
            <div className="space-y-3">
              <Button
                onClick={() => {
                  setShowPassengerCount(false);
                  setShowBookingConfirm(true);
                }}
                className="w-full bg-[#E11D48] hover:bg-[#BE123C] text-white py-6 text-lg font-bold uppercase"
              >
                Continue with {passengerCount} {passengerCount === 1 ? 'Seat' : 'Seats'}
              </Button>
              {selectedVehicle !== 'special' && (
                <Button
                  onClick={() => {
                    setShowPassengerCount(false);
                    setShowLobbyList(true);
                  }}
                  variant="outline"
                  className="w-full py-6 text-lg font-semibold border-2 border-[#E11D48] text-[#E11D48] hover:bg-[#FFF1F2]"
                >
                  <Users className="w-5 h-5 mr-2" />
                  Browse Available Lobbies
                </Button>
              )}
              <Button
                onClick={() => {
                  setShowPassengerCount(false);
                  setPassengerCount(1);
                }}
                variant="outline"
                className="w-full py-6 text-lg font-semibold"
              >
                Cancel
              </Button>
            </div>
          </div>
        </div>
      )}

      {/* Booking Confirmation Modal */}
      {showBookingConfirm && (
        <div className="fixed inset-0 bg-black/50 z-[2000] flex items-end">
          <div className="bg-white w-full rounded-t-3xl p-6">
            <h2 className="text-2xl font-bold text-[#121212] mb-6">Confirm Booking</h2>

            {/* Trip Details */}
            <div className="space-y-4 mb-6">
              <div className="flex items-start gap-3">
                <Navigation className="w-5 h-5 text-[#E11D48] mt-1" />
                <div>
                  <p className="text-sm text-[#64748B]">Pickup</p>
                  <p className="font-semibold text-[#121212]">{pickup}</p>
                </div>
              </div>
              <div className="flex items-start gap-3">
                <Navigation className="w-5 h-5 text-green-600 mt-1" />
                <div>
                  <p className="text-sm text-[#64748B]">Drop-off</p>
                  <p className="font-semibold text-[#121212]">{dropoff}</p>
                </div>
              </div>
            </div>

            {/* Ride Type */}
            <div className="bg-[#FFF1F2] border-2 border-[#E11D48] rounded-xl p-4 mb-6">
              <div className="flex items-center justify-between">
                <div className="flex items-center gap-3">
                  <span className="text-4xl">{selectedVehicle === 'share' ? '' : ''}</span>
                  <div>
                    <p className="font-bold text-[#121212]">
                      {selectedVehicle === 'share' ? 'Share Ride' : 'Special Ride'}
                    </p>
                    <p className="text-sm text-[#64748B]">
                      {selectedVehicle === 'share' ? 'Shared with others' : 'Private ride'}
                    </p>
                  </div>
                </div>
                <p className="text-2xl font-bold text-[#E11D48]">₱{getPrice()}</p>
              </div>
            </div>

            {/* Payment Method */}
            <div className="mb-6">
              <p className="text-sm font-semibold text-[#64748B] mb-3">Payment Method</p>
              <div className="grid grid-cols-2 gap-3">
                <button
                  onClick={() => setPaymentMethod('GCASH')}
                  className={`p-4 border-2 rounded-xl transition-all ${
                    paymentMethod === 'GCASH'
                      ? 'border-[#E11D48] bg-[#FFF1F2]'
                      : 'border-[#E2E8F0]'
                  }`}
                >
                  <div className="flex flex-col items-center gap-2">
                    <CreditCard className="w-6 h-6 text-[#0066FF]" />
                    <span className="font-semibold text-[#121212]">GCash</span>
                  </div>
                </button>
                <button
                  onClick={() => setPaymentMethod('COD')}
                  className={`p-4 border-2 rounded-xl transition-all ${
                    paymentMethod === 'COD'
                      ? 'border-[#E11D48] bg-[#FFF1F2]'
                      : 'border-[#E2E8F0]'
                  }`}
                >
                  <div className="flex flex-col items-center gap-2">
                    <span className="text-2xl"></span>
                    <span className="font-semibold text-[#121212]">Cash</span>
                  </div>
                </button>
              </div>
            </div>

            {/* Action Buttons */}
            <div className="space-y-3">
              <Button
                onClick={handleConfirmBooking}
                className="w-full bg-[#E11D48] hover:bg-[#BE123C] text-white py-6 text-lg font-bold uppercase"
              >
                Confirm Booking
              </Button>
              <Button
                onClick={() => setShowBookingConfirm(false)}
                variant="outline"
                className="w-full py-6 text-lg font-semibold"
              >
                Cancel
              </Button>
            </div>
          </div>
        </div>
      )}

      {/* Searching for Driver Modal */}
      {rideStatus === 'searching' && !isSearchMinimized && (
        <div className="fixed inset-0 bg-black/50 z-[2000] flex items-center justify-center p-4">
          <Card className="bg-white p-8 max-w-sm w-full text-center relative">
            {/* Minimize Button */}
            <button
              onClick={() => setIsSearchMinimized(true)}
              className="absolute top-4 right-4 w-8 h-8 flex items-center justify-center rounded-full bg-[#F1F5F9] hover:bg-[#E2E8F0] transition-colors"
            >
              <ChevronDown className="w-5 h-5 text-[#64748B]" />
            </button>

            <div className="w-20 h-20 bg-[#FFF1F2] rounded-full flex items-center justify-center mx-auto mb-4 animate-pulse">
              <span className="text-4xl"></span>
            </div>
            <h3 className="text-xl font-bold text-[#121212] mb-2">Finding a Driver...</h3>
            <p className="text-[#64748B] mb-6">Please wait while we find you a nearby driver</p>
            <Button
              onClick={handleCancelRide}
              variant="outline"
              className="w-full"
            >
              Cancel Request
            </Button>
          </Card>
        </div>
      )}

      {/* Minimized Floating Icon */}
      {rideStatus === 'searching' && isSearchMinimized && (
        <button
          onClick={() => setIsSearchMinimized(false)}
          className="fixed bottom-24 right-4 z-[2000] w-16 h-16 bg-[#E11D48] rounded-full shadow-2xl flex items-center justify-center hover:bg-[#BE123C] transition-all hover:scale-110"
        >
          <div className="relative">
            <span className="text-3xl animate-pulse"></span>
            <div className="absolute -top-1 -right-1 w-3 h-3 bg-green-500 rounded-full animate-ping"></div>
            <div className="absolute -top-1 -right-1 w-3 h-3 bg-green-500 rounded-full"></div>
          </div>
        </button>
      )}

      {/* Share Ride Lobby */}
      {showShareLobby && (
        <ShareRideLobby
          pickup={pickup}
          pickupAddress={pickupAddress}
          dropoff={dropoff}
          dropoffAddress={dropoffAddress}
          passengerCount={passengerCount}
          pricePerSeat={sharedRidePrice}
          onDriverFound={(lobbyId) => {
            // Don't close the lobby - let customers see driver info in the lobby itself
            // Just update the status for tracking
            setRideStatus('driver-found');
            console.log('✅ Driver found for lobby:', lobbyId);
          }}
          onClose={() => {
            setShowShareLobby(false);
          }}
        />
      )}

      {/* Browse Available Lobbies Modal */}
      {showLobbyList && (
        <BrowseAvailableLobbies
          dropoffAddress={dropoffAddress || dropoff}
          onLobbyJoined={() => {
            setShowLobbyList(false);
            setShowShareLobby(true);
          }}
          onClose={() => {
            setShowLobbyList(false);
          }}
        />
      )}

      {/* Driver Accepted Popup */}
      {driverAcceptedPopup && (
        <div className="fixed inset-0 bg-black/50 z-[3000] flex items-center justify-center p-4">
          <Card className="bg-white p-8 max-w-sm w-full text-center animate-in fade-in zoom-in duration-300">
            <div className="mb-4">
              <div className="w-20 h-20 bg-[#E11D48] rounded-full flex items-center justify-center mx-auto mb-4 text-4xl">
                {driverAcceptedPopup.driverPhoto}
              </div>
              <h3 className="text-2xl font-bold text-[#121212] mb-2">Driver Found! </h3>
              <p className="text-[#64748B] mb-4">Your driver is on the way</p>
            </div>

            {/* Driver Details */}
            <div className="bg-[#F8F9FA] rounded-xl p-4 mb-6 space-y-3">
              <div className="flex items-center justify-between">
                <span className="text-sm text-[#64748B] font-semibold">Driver Name</span>
                <span className="font-bold text-[#121212]">{driverAcceptedPopup.driverName}</span>
              </div>
              <div className="flex items-center justify-between">
                <span className="text-sm text-[#64748B] font-semibold">Plate Number</span>
                <span className="font-bold text-[#121212]">{driverAcceptedPopup.driverPlate}</span>
              </div>
              <div className="flex items-center justify-between">
                <span className="text-sm text-[#64748B] font-semibold">Rating</span>
                <span className="font-bold text-[#E11D48]">⭐ {driverAcceptedPopup.driverRating}</span>
              </div>
            </div>

            <Button
              onClick={() => setDriverAcceptedPopup(null)}
              className="w-full bg-[#E11D48] hover:bg-[#BE123C] text-white py-3 text-lg font-bold"
            >
              Got it! 
            </Button>
          </Card>
        </div>
      )}

      {/* Driver Status Update Popup */}
      {driverStatusPopup && (
        <div className="fixed inset-0 bg-black/50 z-[3000] flex items-end">
          <div className="bg-white w-full rounded-t-3xl p-6 animate-in slide-in-from-bottom duration-300">
            <div className="max-w-sm mx-auto">
              {/* Status Icon */}
              <div className="w-16 h-16 bg-gradient-to-br from-[#E11D48] to-[#BE123C] rounded-full flex items-center justify-center mx-auto mb-4 text-3xl">
                {driverStatusPopup.status === 'on-the-way' && ''}
                {driverStatusPopup.status === 'arrived' && ''}
                {driverStatusPopup.status === 'pickup' && ''}
                {driverStatusPopup.status === 'drop-off' && ''}
                {driverStatusPopup.status === 'payment' && ''}
                {driverStatusPopup.status === 'completed' && ''}
              </div>

              {/* Status Message */}
              <h3 className="text-2xl font-bold text-[#121212] text-center mb-2">
                {driverStatusPopup.status === 'on-the-way' && 'Driver On The Way'}
                {driverStatusPopup.status === 'arrived' && 'Driver Arrived'}
                {driverStatusPopup.status === 'pickup' && 'Picked Up!'}
                {driverStatusPopup.status === 'drop-off' && 'Arrived at Destination'}
                {driverStatusPopup.status === 'payment' && 'Complete Payment'}
                {driverStatusPopup.status === 'completed' && 'Ride Completed!'}
              </h3>

              <p className="text-[#64748B] text-center mb-6">{driverStatusPopup.message}</p>

              {/* Status Details */}
              <div className="bg-[#F8F9FA] rounded-xl p-4 mb-6">
                <div className="flex items-center justify-between">
                  <span className="text-sm text-[#64748B]">Status Update</span>
                  <span className="font-bold text-[#121212]">
                    {driverStatusPopup.status === 'on-the-way' && 'On the way'}
                    {driverStatusPopup.status === 'arrived' && 'Arrived'}
                    {driverStatusPopup.status === 'pickup' && 'Picked up'}
                    {driverStatusPopup.status === 'drop-off' && 'At destination'}
                    {driverStatusPopup.status === 'payment' && 'Payment pending'}
                    {driverStatusPopup.status === 'completed' && 'Completed'}
                  </span>
                </div>
                <div className="flex items-center justify-between mt-3">
                  <span className="text-sm text-[#64748B]">Time</span>
                  <span className="text-sm text-[#121212]">Just now</span>
                </div>
              </div>

              <Button
                onClick={() => setDriverStatusPopup(null)}
                className="w-full bg-[#E11D48] hover:bg-[#BE123C] text-white py-3 text-lg font-bold"
              >
                OK 
              </Button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

import { useState, useEffect } from "react";
import { MapPin, Users, Clock, X, ChevronDown, MessageCircle, User, Minimize2 } from "lucide-react";
import { Button } from "../ui/button";
import { Card } from "../ui/card";
import { Badge } from "../ui/badge";
import { useAuth } from "../../contexts/AuthContext";

interface LobbyPassenger {
  id: string;
  name: string;
  emoji: string;
  joinedAt: string;
  pickup: string;  // Individual pickup location
  pickupAddress: string;  // Individual pickup address
}

interface ShareRideLobby {
  id: string;
  pickup: string;
  pickupAddress: string;
  dropoff: string;
  dropoffAddress: string;
  passengers: LobbyPassenger[];
  maxSeats: number;
  pricePerSeat: number;
  status: 'waiting' | 'driver-found' | 'in-progress' | 'completed';
  driverName?: string;
  driverPlate?: string;
  driverRating?: string;
  createdAt: string;
}

interface ShareRideLobbyProps {
  pickup: string;
  pickupAddress: string;
  dropoff: string;
  dropoffAddress: string;
  passengerCount?: number; // New prop
  pricePerSeat?: number; // New prop for dynamic pricing
  onDriverFound: (driverId: string) => void;
  onClose: () => void;
}

export default function ShareRideLobby({
  pickup,
  pickupAddress,
  dropoff,
  dropoffAddress,
  passengerCount = 1, // Default to 1
  pricePerSeat = 15, // Default price
  onDriverFound,
  onClose
}: ShareRideLobbyProps) {
  const { user } = useAuth();
  const [lobby, setLobby] = useState<ShareRideLobby | null>(null);
  const [isMinimized, setIsMinimized] = useState(false);
  const [showLeaveConfirm, setShowLeaveConfirm] = useState(false);

  // Initialize or join lobby
  useEffect(() => {
    const existingLobby = findOrCreateLobby();
    setLobby(existingLobby);

    // Poll for updates every 2 seconds
    const interval = setInterval(() => {
      const updatedLobby = loadLobby(existingLobby.id);
      if (updatedLobby) {
        setLobby(updatedLobby);

        // Check if driver was found
        if (updatedLobby.status === 'driver-found' && updatedLobby.driverName) {
          onDriverFound(updatedLobby.id);
        }
      }
    }, 2000);

    // Listen for storage events (cross-tab sync)
    const handleStorageChange = (e: StorageEvent) => {
      if (e.key === 'trikeserve_share_lobbies') {
        const updatedLobby = loadLobby(existingLobby.id);
        if (updatedLobby) {
          setLobby(updatedLobby);
        }
      }
    };

    window.addEventListener('storage', handleStorageChange);

    return () => {
      clearInterval(interval);
      window.removeEventListener('storage', handleStorageChange);
    };
  }, []);

  const findOrCreateLobby = (): ShareRideLobby => {
    const lobbiesData = localStorage.getItem('trikeserve_share_lobbies');
    let lobbies: ShareRideLobby[] = [];

    if (lobbiesData) {
      try {
        lobbies = JSON.parse(lobbiesData);
      } catch (error) {
        console.error('Error parsing lobbies:', error);
      }
    }

    // First, check if user is already in an existing lobby
    const existingUserLobby = lobbies.find(l => 
      l.status === 'waiting' &&
      l.passengers.some(p => p.id === user?.id || p.id.startsWith(`${user?.id}_companion_`))
    );

    if (existingUserLobby) {
      console.log('✅ User already in lobby, rejoining:', existingUserLobby.id);
      return existingUserLobby;
    }

    // Find matching lobby with same drop-off and available seats
    const matchingLobby = lobbies.find(l => 
      isSameRoute(l.pickup, l.dropoff, pickup, dropoff) &&
      l.passengers.length + passengerCount <= l.maxSeats && // Check if enough seats
      l.status === 'waiting' &&
      !l.passengers.some(p => p.id === user?.id)
    );

    if (matchingLobby) {
      // Join existing lobby - add main passenger and companions
      const mainPassenger: LobbyPassenger = {
        id: user?.id || `user_${Date.now()}`,
        name: user?.name || 'Customer',
        emoji: getRandomEmoji(),
        joinedAt: new Date().toISOString(),
        pickup: pickup,
        pickupAddress: pickupAddress
      };

      matchingLobby.passengers.push(mainPassenger);

      // Add companions if passenger count > 1
      for (let i = 1; i < passengerCount; i++) {
        const companion: LobbyPassenger = {
          id: `${user?.id || `user_${Date.now()}`}_companion_${i}`,
          name: `+${i} Companion`,
          emoji: '',
          joinedAt: new Date().toISOString(),
          pickup: pickup,
          pickupAddress: pickupAddress
        };
        matchingLobby.passengers.push(companion);
      }

      saveLobby(matchingLobby);

      // Update ride request with new passenger count
      createRideRequest(matchingLobby);

      console.log('✅ Joined existing lobby:', matchingLobby.id);
      return matchingLobby;
    } else {
      // Create new lobby - add main passenger and companions
      const mainPassenger: LobbyPassenger = {
        id: user?.id || `user_${Date.now()}`,
        name: user?.name || 'Customer',
        emoji: getRandomEmoji(),
        joinedAt: new Date().toISOString(),
        pickup: pickup,
        pickupAddress: pickupAddress
      };

      const passengers: LobbyPassenger[] = [mainPassenger];

      // Add companions if passenger count > 1
      for (let i = 1; i < passengerCount; i++) {
        const companion: LobbyPassenger = {
          id: `${user?.id || `user_${Date.now()}`}_companion_${i}`,
          name: `+${i} Companion`,
          emoji: '',
          joinedAt: new Date().toISOString(),
          pickup: pickup,
          pickupAddress: pickupAddress
        };
        passengers.push(companion);
      }

      const newLobby: ShareRideLobby = {
        id: `lobby_${Date.now()}`,
        pickup,
        pickupAddress,
        dropoff,
        dropoffAddress,
        passengers,
        maxSeats: 3,
        pricePerSeat: pricePerSeat,
        status: 'waiting',
        createdAt: new Date().toISOString()
      };

      lobbies.push(newLobby);
      localStorage.setItem('trikeserve_share_lobbies', JSON.stringify(lobbies));

      // Also create ride request for drivers
      createRideRequest(newLobby);

      console.log('✅ Created new lobby:', newLobby.id);
      return newLobby;
    }
  };

  const loadLobby = (lobbyId: string): ShareRideLobby | null => {
    const lobbiesData = localStorage.getItem('trikeserve_share_lobbies');
    if (!lobbiesData) return null;

    try {
      const lobbies: ShareRideLobby[] = JSON.parse(lobbiesData);
      return lobbies.find(l => l.id === lobbyId) || null;
    } catch (error) {
      console.error('Error loading lobby:', error);
      return null;
    }
  };

  const saveLobby = (updatedLobby: ShareRideLobby) => {
    const lobbiesData = localStorage.getItem('trikeserve_share_lobbies');
    let lobbies: ShareRideLobby[] = [];

    if (lobbiesData) {
      try {
        lobbies = JSON.parse(lobbiesData);
      } catch (error) {
        console.error('Error parsing lobbies:', error);
      }
    }

    const index = lobbies.findIndex(l => l.id === updatedLobby.id);
    if (index >= 0) {
      lobbies[index] = updatedLobby;
    } else {
      lobbies.push(updatedLobby);
    }

    localStorage.setItem('trikeserve_share_lobbies', JSON.stringify(lobbies));

    // Trigger storage event for cross-tab sync
    window.dispatchEvent(new StorageEvent('storage', {
      key: 'trikeserve_share_lobbies',
      newValue: JSON.stringify(lobbies)
    }));
  };

  const createRideRequest = (lobby: ShareRideLobby) => {
    const rideRequest = {
      id: `req_${lobby.id}`,
      lobbyId: lobby.id,
      type: 'shared',
      pickup: lobby.pickup,
      dropoff: lobby.dropoff,
      pickupAddress: lobby.pickupAddress,
      dropoffAddress: lobby.dropoffAddress,
      payment: 'PREPAID',
      amount: lobby.pricePerSeat * lobby.passengers.length,
      passengers: lobby.passengers.length,
      maxPassengers: lobby.maxSeats,
      passengerDetails: lobby.passengers,
      customerName: lobby.passengers.length > 1 
        ? `${lobby.passengers.length} Passengers` 
        : lobby.passengers[0]?.name || 'Customer',
      customerPhoto: '',
      distance: '2.5 km',
      estimatedTime: '7 mins',
      status: 'waiting',
      createdAt: lobby.createdAt
    };

    const existingRequests = localStorage.getItem('trikeserve_ride_requests');
    let requests = [];
    if (existingRequests) {
      try {
        requests = JSON.parse(existingRequests);
      } catch (error) {
        console.error('Error parsing requests:', error);
      }
    }

    // Check if request already exists
    const existingIndex = requests.findIndex((r: any) => r.lobbyId === lobby.id);
    if (existingIndex >= 0) {
      requests[existingIndex] = rideRequest;
    } else {
      requests.push(rideRequest);
    }

    localStorage.setItem('trikeserve_ride_requests', JSON.stringify(requests));
  };

  const handleLeaveLobby = () => {
    if (!lobby) return;

    const lobbiesData = localStorage.getItem('trikeserve_share_lobbies');
    if (!lobbiesData) return;

    try {
      let lobbies: ShareRideLobby[] = JSON.parse(lobbiesData);
      const targetLobby = lobbies.find(l => l.id === lobby.id);

      if (targetLobby) {
        // Remove current user and their companions from passengers
        targetLobby.passengers = targetLobby.passengers.filter(p => {
          // Remove the main user
          if (p.id === user?.id) return false;
          // Remove companions (they have id like "userId_companion_1")
          if (p.id.startsWith(`${user?.id}_companion_`)) return false;
          return true;
        });

        // Check if lobby is now empty or user was the only one left
        if (targetLobby.passengers.length === 0) {
          // Delete lobby if empty - user was the only one left
          lobbies = lobbies.filter(l => l.id !== lobby.id);
          console.log(`Lobby ${lobby.id} deleted - last passenger left`);

          // Also remove the associated ride request
          const requestsData = localStorage.getItem('trikeserve_ride_requests');
          if (requestsData) {
            try {
              let requests = JSON.parse(requestsData);
              requests = requests.filter((r: any) => r.lobbyId !== lobby.id);
              localStorage.setItem('trikeserve_ride_requests', JSON.stringify(requests));
              console.log(`Ride request for lobby ${lobby.id} deleted`);
            } catch (error) {
              console.error('Error removing ride request:', error);
            }
          }
        } else {
          // Update the lobby with remaining passengers
          lobbies = lobbies.map(l => l.id === lobby.id ? targetLobby : l);

          // Update the ride request with new passenger count
          const requestsData = localStorage.getItem('trikeserve_ride_requests');
          if (requestsData) {
            try {
              let requests = JSON.parse(requestsData);
              const requestIndex = requests.findIndex((r: any) => r.lobbyId === lobby.id);
              if (requestIndex >= 0) {
                requests[requestIndex].passengers = targetLobby.passengers.length;
                requests[requestIndex].amount = targetLobby.pricePerSeat * targetLobby.passengers.length;
                requests[requestIndex].passengerDetails = targetLobby.passengers;
                requests[requestIndex].customerName = targetLobby.passengers.length > 1 
                  ? `${targetLobby.passengers.length} Passengers` 
                  : targetLobby.passengers[0]?.name || 'Customer';
                localStorage.setItem('trikeserve_ride_requests', JSON.stringify(requests));
                console.log(`Ride request for lobby ${lobby.id} updated - ${targetLobby.passengers.length} passengers remaining`);
              }
            } catch (error) {
              console.error('Error updating ride request:', error);
            }
          }
        }

        localStorage.setItem('trikeserve_share_lobbies', JSON.stringify(lobbies));

        // Trigger storage event for cross-tab sync
        window.dispatchEvent(new StorageEvent('storage', {
          key: 'trikeserve_share_lobbies',
          newValue: JSON.stringify(lobbies)
        }));
      }
    } catch (error) {
      console.error('Error leaving lobby:', error);
    }

    onClose();
  };

  const isSameRoute = (l1Pickup: string, l1Dropoff: string, l2Pickup: string, l2Dropoff: string) => {
    // Only match drop-off location, allow different pickups
    const dropoffMatch = l1Dropoff.toLowerCase().trim() === l2Dropoff.toLowerCase().trim();
    return dropoffMatch;
  };

  const getRandomEmoji = () => {
    const emojis = ['', '', '', '', '', '', '‍', '‍', '‍', '‍'];
    return emojis[Math.floor(Math.random() * emojis.length)];
  };

  const getWaitingTime = () => {
    if (!lobby) return '0s';
    const elapsed = Date.now() - new Date(lobby.createdAt).getTime();
    const seconds = Math.floor(elapsed / 1000);
    if (seconds < 60) return `${seconds}s`;
    const minutes = Math.floor(seconds / 60);
    return `${minutes}m ${seconds % 60}s`;
  };

  if (!lobby) return null;

  // Minimized floating icon
  if (isMinimized) {
    return (
      <button
        onClick={() => setIsMinimized(false)}
        className="fixed bottom-24 right-4 z-[2000] shadow-2xl"
      >
        <div className="relative">
          <div className="w-16 h-16 bg-[#E11D48] rounded-full flex items-center justify-center hover:bg-[#BE123C] transition-all hover:scale-110">
            <Users className="w-8 h-8 text-white" />
          </div>
          {/* Passenger count badge */}
          <div className="absolute -top-1 -right-1 w-7 h-7 bg-white rounded-full border-2 border-[#E11D48] flex items-center justify-center">
            <span className="text-xs font-bold text-[#E11D48]">{lobby.passengers.length}/{lobby.maxSeats}</span>
          </div>
          {/* Pulse animation */}
          <div className="absolute inset-0 bg-[#E11D48] rounded-full animate-ping opacity-20"></div>
        </div>
      </button>
    );
  }

  // Full lobby view
  return (
    <>
      <div className="fixed inset-0 bg-black/50 z-[2000] flex items-end">
        <div className="bg-white w-full rounded-t-3xl max-h-[90vh] overflow-hidden flex flex-col animate-slide-up">
          {/* Header */}
          <div className="p-5 border-b border-[#E2E8F0]">
            <div className="flex items-center justify-between mb-2">
              <div className="flex items-center gap-3">
                <div className="w-10 h-10 bg-[#FFF1F2] rounded-full flex items-center justify-center">
                  <Users className="w-5 h-5 text-[#E11D48]" />
                </div>
                <div>
                  <h2 className="text-xl font-bold text-[#121212]">Share Ride Lobby</h2>
                  <p className="text-xs text-[#64748B]">Waiting: {getWaitingTime()}</p>
                </div>
              </div>
              <div className="flex items-center gap-2">
                <button
                  onClick={() => setIsMinimized(true)}
                  className="w-9 h-9 flex items-center justify-center rounded-full bg-[#F1F5F9] hover:bg-[#E2E8F0] transition-colors"
                >
                  <ChevronDown className="w-5 h-5 text-[#64748B]" />
                </button>
                <button
                  onClick={() => setShowLeaveConfirm(true)}
                  className="w-9 h-9 flex items-center justify-center rounded-full bg-[#F1F5F9] hover:bg-[#E2E8F0] transition-colors"
                >
                  <X className="w-5 h-5 text-[#64748B]" />
                </button>
              </div>
            </div>

            {/* Status Badge */}
            <Badge className={
              lobby.status === 'driver-found' 
                ? 'bg-green-500 text-white' 
                : 'bg-yellow-500 text-white'
            }>
              {lobby.status === 'driver-found' ? '✓ Driver Found!' : ' Finding Driver...'}
            </Badge>
          </div>

          {/* Route Info */}
          <div className="px-5 py-4 bg-gradient-to-r from-[#FFF1F2] to-[#FFF7ED] border-b border-[#E2E8F0]">
            <div className="space-y-2">
              <div className="flex items-start gap-2">
                <MapPin className="w-4 h-4 text-[#121212] mt-0.5 flex-shrink-0" />
                <div className="flex-1 min-w-0">
                  <p className="text-xs text-[#64748B] uppercase tracking-wide font-semibold">Pickup</p>
                  <p className="font-bold text-[#121212]">{lobby.pickup}</p>
                  <p className="text-xs text-[#64748B]">{lobby.pickupAddress}</p>
                </div>
              </div>
              <div className="flex items-start gap-2">
                <MapPin className="w-4 h-4 text-[#E11D48] mt-0.5 flex-shrink-0" />
                <div className="flex-1 min-w-0">
                  <p className="text-xs text-[#64748B] uppercase tracking-wide font-semibold">Drop-off</p>
                  <p className="font-bold text-[#121212]">{lobby.dropoff}</p>
                  <p className="text-xs text-[#64748B]">{lobby.dropoffAddress}</p>
                </div>
              </div>
            </div>
          </div>

          {/* Passengers Section */}
          <div className="flex-1 overflow-y-auto p-5">
            <div className="mb-4">
              <div className="flex items-center justify-between mb-3">
                <h3 className="text-sm font-bold text-[#64748B] uppercase tracking-wide">Passengers</h3>
                <span className="text-sm font-bold text-[#E11D48]">
                  {lobby.passengers.length}/{lobby.maxSeats} Seats
                </span>
              </div>

              {/* Passenger Cards */}
              <div className="space-y-2">
                {lobby.passengers.map((passenger, index) => {
                  // Check if this passenger belongs to the current user (main or companion)
                  const isCurrentUserOrCompanion = 
                    passenger.id === user?.id || 
                    passenger.id.startsWith(`${user?.id}_companion_`);

                  return (
                    <Card 
                      key={passenger.id}
                      className={`p-4 border-2 transition-all ${
                        isCurrentUserOrCompanion
                          ? 'border-[#E11D48] bg-[#FFF1F2]' 
                          : 'border-[#E2E8F0] bg-white'
                      }`}
                    >
                      <div className="flex items-center gap-3">
                        <div className="w-12 h-12 rounded-full bg-gradient-to-br from-[#E11D48] to-[#BE123C] flex items-center justify-center text-2xl">
                          {passenger.emoji}
                        </div>
                        <div className="flex-1">
                          <div className="flex items-center gap-2">
                            <p className="font-bold text-[#121212]">{passenger.name}</p>
                            {passenger.id === user?.id && (
                              <Badge variant="outline" className="border-[#E11D48] text-[#E11D48] text-[10px]">
                                YOU
                              </Badge>
                            )}
                          </div>
                          <p className="text-xs text-[#64748B]">
                            Joined {new Date(passenger.joinedAt).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
                          </p>
                        </div>
                        {index === 0 && (
                          <Badge className="bg-purple-500 text-white text-[10px]">
                            HOST
                          </Badge>
                        )}
                      </div>
                    </Card>
                  );
                })}

                {/* Empty Seats */}
                {Array.from({ length: lobby.maxSeats - lobby.passengers.length }).map((_, index) => (
                  <Card 
                    key={`empty-${index}`}
                    className="p-4 border-2 border-dashed border-[#E2E8F0] bg-[#F8F9FA]"
                  >
                    <div className="flex items-center gap-3">
                      <div className="w-12 h-12 rounded-full bg-gray-200 flex items-center justify-center">
                        <Users className="w-6 h-6 text-gray-400" />
                      </div>
                      <p className="text-sm text-[#94A3B8] italic">Waiting for passenger...</p>
                    </div>
                  </Card>
                ))}
              </div>
            </div>

            {/* Driver Info (when found) */}
            {lobby.status === 'driver-found' && lobby.driverName && (
              <Card className="p-4 border-2 border-green-500 bg-green-50 mb-4">
                <div className="flex items-center gap-3">
                  <div className="w-14 h-14 rounded-full bg-green-200 flex items-center justify-center text-3xl">
                    ‍✈️
                  </div>
                  <div className="flex-1">
                    <p className="text-xs text-green-700 font-semibold uppercase tracking-wide mb-0.5">Your Driver</p>
                    <p className="font-bold text-[#121212] text-lg">{lobby.driverName}</p>
                    <div className="flex items-center gap-2">
                      <span className="text-xs text-[#64748B]">{lobby.driverPlate}</span>
                      {lobby.driverRating && (
                        <>
                          <span className="text-[#64748B]">•</span>
                          <div className="flex items-center gap-1">
                            <span className="text-yellow-500">⭐</span>
                            <span className="text-xs font-semibold text-[#121212]">{lobby.driverRating}</span>
                          </div>
                        </>
                      )}
                    </div>
                  </div>
                  <Button
                    size="icon"
                    className="bg-green-500 hover:bg-green-600 text-white"
                  >
                    <MessageCircle className="w-5 h-5" />
                  </Button>
                </div>
              </Card>
            )}

            {/* Waiting Animation */}
            {lobby.status === 'waiting' && (
              <div className="text-center py-6">
                <div className="w-16 h-16 bg-[#FFF1F2] rounded-full flex items-center justify-center mx-auto mb-3 animate-pulse">
                  <span className="text-4xl"></span>
                </div>
                <p className="text-sm text-[#64748B] mb-1">
                  {lobby.passengers.length < lobby.maxSeats 
                    ? 'Waiting for more passengers...' 
                    : 'Finding the best driver for you...'}
                </p>
                <p className="text-xs text-[#94A3B8]">
                  The more passengers, the faster we find a driver!
                </p>
              </div>
            )}
          </div>

          {/* Footer - Price Info */}
          <div className="p-5 border-t border-[#E2E8F0] bg-white">
            <div className="flex items-center justify-between mb-3">
              <div>
                <p className="text-sm text-[#64748B]">Your Fare</p>
                <p className="text-3xl font-bold text-[#E11D48]">₱{pricePerSeat}</p>
                {lobby.passengers.length > 1 && (
                  <p className="text-xs text-[#94A3B8]">
                    ₱{pricePerSeat} per person
                  </p>
                )}
              </div>
              <div className="text-right">
                <p className="text-sm text-[#64748B]">Total Trip Cost</p>
                <p className="text-xl font-bold text-[#121212]">
                  ₱{pricePerSeat * lobby.passengers.length}
                </p>
                <p className="text-xs text-[#94A3B8]">
                  {lobby.passengers.length} × ₱{pricePerSeat}
                </p>
              </div>
            </div>

            {lobby.passengers.length === lobby.maxSeats && (
              <div className="bg-green-50 border border-green-200 rounded-lg p-3 text-center">
                <p className="text-sm text-green-700 font-semibold">
                   Lobby Full! Prioritizing your ride request...
                </p>
              </div>
            )}
          </div>
        </div>
      </div>

      {/* Leave Confirmation Modal */}
      {showLeaveConfirm && (
        <div className="fixed inset-0 bg-black/70 z-[2100] flex items-center justify-center p-4">
          <Card className="bg-white p-6 max-w-sm w-full">
            <h3 className="text-lg font-bold text-[#121212] mb-2">Leave Lobby?</h3>
            <p className="text-sm text-[#64748B] mb-6">
              Are you sure you want to leave? You'll need to find a new ride.
            </p>
            <div className="flex gap-3">
              <Button
                variant="outline"
                onClick={() => setShowLeaveConfirm(false)}
                className="flex-1"
              >
                CANCEL
              </Button>
              <Button
                onClick={handleLeaveLobby}
                className="flex-1 bg-red-500 hover:bg-red-600 text-white"
              >
                LEAVE
              </Button>
            </div>
          </Card>
        </div>
      )}
    </>
  );
}

import { useState, useEffect } from "react";
import { MapPin, Users, Clock, X, ChevronDown, MessageCircle, User, Minimize2 } from "lucide-react";
import { Button } from "../ui/button";
import { Card } from "../ui/card";
import { Badge } from "../ui/badge";
import { useAuth } from "../../contexts/AuthContext";
import { supabaseHelpers } from "@/lib/supabase";

interface LobbyPassenger {
  id: string;
  name: string;
  emoji: string;
  joinedAt: string;
  pickup: string;  // Individual pickup location
  pickupAddress: string;  // Individual pickup address
}

interface ShareRideLobby {
  id: string;
  customer_id?: string;
  pickup_location: string;
  pickup_address: string;
  dropoff_location: string;
  dropoff_address: string;
  passengers_json?: LobbyPassenger[];
  max_seats: number;
  price_per_seat: number;
  status: 'waiting' | 'driver_found' | 'in_progress' | 'completed';
  driver_name?: string;
  driver_plate?: string;
  driver_rating?: string;
  created_at: string;
}

interface ShareRideLobbyProps {
  pickup: string;
  pickupAddress: string;
  dropoff: string;
  dropoffAddress: string;
  passengerCount?: number;
  pricePerSeat?: number;
  onDriverFound: (lobbyId: string) => void;
  onClose: () => void;
}

export default function ShareRideLobby({
  pickup,
  pickupAddress,
  dropoff,
  dropoffAddress,
  passengerCount = 1,
  pricePerSeat = 15,
  onDriverFound,
  onClose
}: ShareRideLobbyProps) {
  const { user } = useAuth();
  const [lobby, setLobby] = useState<ShareRideLobby | null>(null);
  const [isMinimized, setIsMinimized] = useState(false);
  const [showLeaveConfirm, setShowLeaveConfirm] = useState(false);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  // Initialize or join lobby on mount
  useEffect(() => {
    const initializeLobby = async () => {
      try {
        setLoading(true);
        const existingLobby = await findOrCreateLobby();
        if (existingLobby) {
          setLobby(existingLobby);

          // Set up real-time subscription
          const unsubscribe = supabaseHelpers.subscribeLobbyUpdates(
            existingLobby.id,
            (updatedLobbyData) => {
              console.log(' Lobby updated:', updatedLobbyData);
              setLobby(prevLobby => ({
                ...prevLobby!,
                ...updatedLobbyData,
                passengers_json: updatedLobbyData.passengers_json || []
              }));

              // Check if driver was found
              if (updatedLobbyData.status === 'driver_found' && updatedLobbyData.driver_name) {
                onDriverFound(updatedLobbyData.id);
              }
            }
          );

          return unsubscribe;
        }
      } catch (err) {
        console.error('Error initializing lobby:', err);
        setError('Failed to create lobby');
      } finally {
        setLoading(false);
      }
    };

    let unsubscribe: (() => void) | undefined;
    initializeLobby().then(unsub => {
      unsubscribe = unsub;
    });

    return () => {
      if (unsubscribe) unsubscribe();
    };
  }, []);

  const getRandomEmoji = () => {
    const emojis = ['', '', '', '', '', '', '‍', '‍', '‍', '‍'];
    return emojis[Math.floor(Math.random() * emojis.length)];
  };

  const findOrCreateLobby = async (): Promise<ShareRideLobby | null> => {
    try {
      // First, check if user is already in a waiting lobby
      const { data: userLobbies, error: userError } = await supabaseHelpers.getAvailableLobbies();
      if (!userError && userLobbies) {
        const existingUserLobby = userLobbies.find((l: any) => {
          const passengers = Array.isArray(l.passengers_json) ? l.passengers_json : [];
          return passengers.some((p: any) => p.id === user?.id || p.id.startsWith(`${user?.id}_companion_`));
        });

        if (existingUserLobby) {
          console.log('✅ User already in lobby:', existingUserLobby.id);
          return {
            ...existingUserLobby,
            passengers_json: Array.isArray(existingUserLobby.passengers_json) 
              ? existingUserLobby.passengers_json 
              : []
          };
        }
      }

      // Try to find matching lobby with same dropoff
      const { data: matchingLobby, error: matchError } = await supabaseHelpers.getAvailableLobbyByRoute(
        pickupAddress,
        dropoffAddress
      );

      if (!matchError && matchingLobby) {
        const passengers = Array.isArray(matchingLobby.passengers_json) 
          ? matchingLobby.passengers_json 
          : [];

        // Check if we have space
        if (passengers.length + passengerCount <= matchingLobby.max_seats) {
          // Join the lobby
          const mainPassenger: LobbyPassenger = {
            id: user?.id || `user_${Date.now()}`,
            name: user?.name || 'Customer',
            emoji: getRandomEmoji(),
            joinedAt: new Date().toISOString(),
            pickup,
            pickupAddress
          };

          const newPassengers = [...passengers, mainPassenger];

          // Add companions if needed
          for (let i = 1; i < passengerCount; i++) {
            newPassengers.push({
              id: `${user?.id}_companion_${i}`,
              name: `+${i} Companion`,
              emoji: '',
              joinedAt: new Date().toISOString(),
              pickup,
              pickupAddress
            });
          }

          // Update the lobby
          const { data: updated, error: updateError } = await supabaseHelpers.updateLobbyPassengers(
            matchingLobby.id,
            newPassengers
          );

          if (!updateError && updated) {
            console.log('✅ Joined existing lobby:', matchingLobby.id);
            return {
              ...updated,
              passengers_json: Array.isArray(updated.passengers_json) ? updated.passengers_json : []
            };
          }
        }
      }

      // No matching lobby found, create a new one
      const mainPassenger: LobbyPassenger = {
        id: user?.id || `user_${Date.now()}`,
        name: user?.name || 'Customer',
        emoji: getRandomEmoji(),
        joinedAt: new Date().toISOString(),
        pickup,
        pickupAddress
      };

      const passengers: LobbyPassenger[] = [mainPassenger];

      // Add companions if needed
      for (let i = 1; i < passengerCount; i++) {
        passengers.push({
          id: `${user?.id}_companion_${i}`,
          name: `+${i} Companion`,
          emoji: '',
          joinedAt: new Date().toISOString(),
          pickup,
          pickupAddress
        });
      }

      const newLobby = {
        customer_id: user?.id,
        pickup_location: pickup,
        pickup_address: pickupAddress,
        dropoff_location: dropoff,
        dropoff_address: dropoffAddress,
        passengers_json: passengers,
        max_seats: 3,
        price_per_seat: pricePerSeat,
        status: 'waiting'
      };

      const { data: createdLobby, error: createError } = await supabaseHelpers.createShareRideLobby(newLobby);

      if (!createError && createdLobby) {
        console.log('✅ Created new lobby:', createdLobby.id);
        return {
          ...createdLobby,
          passengers_json: Array.isArray(createdLobby.passengers_json) ? createdLobby.passengers_json : []
        };
      }

      setError('Failed to create lobby');
      return null;
    } catch (err) {
      console.error('Error finding or creating lobby:', err);
      setError('Error with lobby system');
      return null;
    }
  };

  const handleLeaveLobby = async () => {
    if (!lobby || !user) return;

    try {
      const { error: leaveError } = await supabaseHelpers.leaveShareRideLobby(
        lobby.id,
        user.id
      );

      if (leaveError) {
        console.error('Error leaving lobby:', leaveError);
        setError('Failed to leave lobby');
        return;
      }

      onClose();
    } catch (err) {
      console.error('Error in handleLeaveLobby:', err);
      setError('Error leaving lobby');
    }
  };

  const getWaitingTime = () => {
    if (!lobby) return '0s';
    const elapsed = Date.now() - new Date(lobby.created_at).getTime();
    const seconds = Math.floor(elapsed / 1000);
    if (seconds < 60) return `${seconds}s`;
    const minutes = Math.floor(seconds / 60);
    return `${minutes}m ${seconds % 60}s`;
  };

  if (loading) {
    return (
      <div className="fixed inset-0 bg-black/50 z-[2000] flex items-center justify-center">
        <div className="bg-white rounded-lg p-8 text-center">
          <div className="animate-spin w-12 h-12 border-4 border-[#E11D48] border-t-transparent rounded-full mx-auto mb-4"></div>
          <p className="text-[#64748B]">Creating lobby...</p>
        </div>
      </div>
    );
  }

  if (error) {
    return (
      <div className="fixed inset-0 bg-black/50 z-[2000] flex items-center justify-center p-4">
        <Card className="bg-white p-6 max-w-sm w-full">
          <h3 className="text-lg font-bold text-red-600 mb-2">Error</h3>
          <p className="text-sm text-[#64748B] mb-6">{error}</p>
          <Button onClick={onClose} className="w-full bg-red-500 hover:bg-red-600">
            Close
          </Button>
        </Card>
      </div>
    );
  }

  if (!lobby) return null;

  // Minimized floating icon
  if (isMinimized) {
    return (
      <button
        onClick={() => setIsMinimized(false)}
        className="fixed bottom-24 right-4 z-[2000] shadow-2xl"
      >
        <div className="relative">
          <div className="w-16 h-16 bg-[#E11D48] rounded-full flex items-center justify-center hover:bg-[#BE123C] transition-all hover:scale-110">
            <Users className="w-8 h-8 text-white" />
          </div>
          <div className="absolute -top-1 -right-1 w-7 h-7 bg-white rounded-full border-2 border-[#E11D48] flex items-center justify-center">
            <span className="text-xs font-bold text-[#E11D48]">
              {(lobby.passengers_json || []).length}/{lobby.max_seats}
            </span>
          </div>
          <div className="absolute inset-0 bg-[#E11D48] rounded-full animate-ping opacity-20"></div>
        </div>
      </button>
    );
  }

  const passengers = lobby.passengers_json || [];

  // Full lobby view
  return (
    <>
      <div className="fixed inset-0 bg-black/50 z-[2000] flex items-end">
        <div className="bg-white w-full rounded-t-3xl max-h-[90vh] overflow-hidden flex flex-col animate-slide-up">
          {/* Header */}
          <div className="p-5 border-b border-[#E2E8F0]">
            <div className="flex items-center justify-between mb-2">
              <div className="flex items-center gap-3">
                <div className="w-10 h-10 bg-[#FFF1F2] rounded-full flex items-center justify-center">
                  <Users className="w-5 h-5 text-[#E11D48]" />
                </div>
                <div>
                  <h2 className="text-xl font-bold text-[#121212]">Share Ride Lobby</h2>
                  <p className="text-xs text-[#64748B]">Waiting: {getWaitingTime()}</p>
                </div>
              </div>
              <div className="flex items-center gap-2">
                <button
                  onClick={() => setIsMinimized(true)}
                  className="w-9 h-9 flex items-center justify-center rounded-full bg-[#F1F5F9] hover:bg-[#E2E8F0] transition-colors"
                >
                  <ChevronDown className="w-5 h-5 text-[#64748B]" />
                </button>
                <button
                  onClick={() => setShowLeaveConfirm(true)}
                  className="w-9 h-9 flex items-center justify-center rounded-full bg-[#F1F5F9] hover:bg-[#E2E8F0] transition-colors"
                >
                  <X className="w-5 h-5 text-[#64748B]" />
                </button>
              </div>
            </div>

            <Badge className={
              lobby.status === 'driver_found' 
                ? 'bg-green-500 text-white' 
                : 'bg-yellow-500 text-white'
            }>
              {lobby.status === 'driver_found' ? '✓ Driver Found!' : ' Finding Driver...'}
            </Badge>
          </div>

          {/* Route Info */}
          <div className="px-5 py-4 bg-gradient-to-r from-[#FFF1F2] to-[#FFF7ED] border-b border-[#E2E8F0]">
            <div className="space-y-2">
              <div className="flex items-start gap-2">
                <MapPin className="w-4 h-4 text-[#121212] mt-0.5 flex-shrink-0" />
                <div className="flex-1 min-w-0">
                  <p className="text-xs text-[#64748B] uppercase tracking-wide font-semibold">Pickup</p>
                  <p className="font-bold text-[#121212]">{lobby.pickup_location}</p>
                  <p className="text-xs text-[#64748B]">{lobby.pickup_address}</p>
                </div>
              </div>
              <div className="flex items-start gap-2">
                <MapPin className="w-4 h-4 text-[#E11D48] mt-0.5 flex-shrink-0" />
                <div className="flex-1 min-w-0">
                  <p className="text-xs text-[#64748B] uppercase tracking-wide font-semibold">Drop-off</p>
                  <p className="font-bold text-[#121212]">{lobby.dropoff_location}</p>
                  <p className="text-xs text-[#64748B]">{lobby.dropoff_address}</p>
                </div>
              </div>
            </div>
          </div>

          {/* Passengers Section */}
          <div className="flex-1 overflow-y-auto p-5">
            <div className="mb-4">
              <div className="flex items-center justify-between mb-3">
                <h3 className="text-sm font-bold text-[#64748B] uppercase tracking-wide">Passengers</h3>
                <span className="text-sm font-bold text-[#E11D48]">
                  {passengers.length}/{lobby.max_seats} Seats
                </span>
              </div>

              {/* Passenger Cards */}
              <div className="space-y-2">
                {passengers.map((passenger, index) => {
                  const isCurrentUserOrCompanion = 
                    passenger.id === user?.id || 
                    passenger.id.startsWith(`${user?.id}_companion_`);

                  return (
                    <Card 
                      key={passenger.id}
                      className={`p-4 border-2 transition-all ${
                        isCurrentUserOrCompanion
                          ? 'border-[#E11D48] bg-[#FFF1F2]' 
                          : 'border-[#E2E8F0] bg-white'
                      }`}
                    >
                      <div className="flex items-center gap-3">
                        <div className="w-12 h-12 rounded-full bg-gradient-to-br from-[#E11D48] to-[#BE123C] flex items-center justify-center text-2xl">
                          {passenger.emoji}
                        </div>
                        <div className="flex-1">
                          <div className="flex items-center gap-2">
                            <p className="font-bold text-[#121212]">{passenger.name}</p>
                            {passenger.id === user?.id && (
                              <Badge variant="outline" className="border-[#E11D48] text-[#E11D48] text-[10px]">
                                YOU
                              </Badge>
                            )}
                          </div>
                          <p className="text-xs text-[#64748B]">
                            Joined {new Date(passenger.joinedAt).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
                          </p>
                        </div>
                        {index === 0 && (
                          <Badge className="bg-purple-500 text-white text-[10px]">
                            HOST
                          </Badge>
                        )}
                      </div>
                    </Card>
                  );
                })}

                {/* Empty Seats */}
                {Array.from({ length: lobby.max_seats - passengers.length }).map((_, index) => (
                  <Card 
                    key={`empty-${index}`}
                    className="p-4 border-2 border-dashed border-[#E2E8F0] bg-[#F8F9FA]"
                  >
                    <div className="flex items-center gap-3">
                      <div className="w-12 h-12 rounded-full bg-gray-200 flex items-center justify-center">
                        <Users className="w-6 h-6 text-gray-400" />
                      </div>
                      <p className="text-sm text-[#94A3B8] italic">Waiting for passenger...</p>
                    </div>
                  </Card>
                ))}
              </div>
            </div>

            {/* Driver Info (when found) */}
            {lobby.status === 'driver_found' && lobby.driver_name && (
              <Card className="p-4 border-2 border-green-500 bg-green-50 mb-4">
                <div className="flex items-center gap-3">
                  <div className="w-14 h-14 rounded-full bg-green-200 flex items-center justify-center text-3xl">
                    ‍✈️
                  </div>
                  <div className="flex-1">
                    <p className="text-xs text-green-700 font-semibold uppercase tracking-wide mb-0.5">Your Driver</p>
                    <p className="font-bold text-[#121212] text-lg">{lobby.driver_name}</p>
                    <div className="flex items-center gap-2">
                      <span className="text-xs text-[#64748B]">{lobby.driver_plate}</span>
                      {lobby.driver_rating && (
                        <>
                          <span className="text-[#64748B]">•</span>
                          <div className="flex items-center gap-1">
                            <span className="text-yellow-500">⭐</span>
                            <span className="text-xs font-semibold text-[#121212]">{lobby.driver_rating}</span>
                          </div>
                        </>
                      )}
                    </div>
                  </div>
                  <Button
                    size="icon"
                    className="bg-green-500 hover:bg-green-600 text-white"
                  >
                    <MessageCircle className="w-5 h-5" />
                  </Button>
                </div>
              </Card>
            )}

            {/* Waiting Animation */}
            {lobby.status === 'waiting' && (
              <div className="text-center py-6">
                <div className="w-16 h-16 bg-[#FFF1F2] rounded-full flex items-center justify-center mx-auto mb-3 animate-pulse">
                  <span className="text-4xl"></span>
                </div>
                <p className="text-sm text-[#64748B] mb-1">
                  {passengers.length < lobby.max_seats 
                    ? 'Waiting for more passengers...' 
                    : 'Finding the best driver for you...'}
                </p>
                <p className="text-xs text-[#94A3B8]">
                  The more passengers, the faster we find a driver!
                </p>
              </div>
            )}
          </div>

          {/* Footer - Price Info */}
          <div className="p-5 border-t border-[#E2E8F0] bg-white">
            <div className="flex items-center justify-between mb-3">
              <div>
                <p className="text-sm text-[#64748B]">Your Fare</p>
                <p className="text-3xl font-bold text-[#E11D48]">₱{pricePerSeat}</p>
                {passengers.length > 1 && (
                  <p className="text-xs text-[#94A3B8]">
                    ₱{pricePerSeat} per person
                  </p>
                )}
              </div>
              <div className="text-right">
                <p className="text-sm text-[#64748B]">Total Trip Cost</p>
                <p className="text-xl font-bold text-[#121212]">
                  ₱{pricePerSeat * passengers.length}
                </p>
                <p className="text-xs text-[#94A3B8]">
                  {passengers.length} × ₱{pricePerSeat}
                </p>
              </div>
            </div>

            {passengers.length === lobby.max_seats && (
              <div className="bg-green-50 border border-green-200 rounded-lg p-3 text-center">
                <p className="text-sm text-green-700 font-semibold">
                   Lobby Full! Prioritizing your ride request...
                </p>
              </div>
            )}
          </div>
        </div>
      </div>

      {/* Leave Confirmation Modal */}
      {showLeaveConfirm && (
        <div className="fixed inset-0 bg-black/70 z-[2100] flex items-center justify-center p-4">
          <Card className="bg-white p-6 max-w-sm w-full">
            <h3 className="text-lg font-bold text-[#121212] mb-2">Leave Lobby?</h3>
            <p className="text-sm text-[#64748B] mb-6">
              Are you sure you want to leave? You'll need to find a new ride.
            </p>
            <div className="flex gap-3">
              <Button
                variant="outline"
                onClick={() => setShowLeaveConfirm(false)}
                className="flex-1"
              >
                CANCEL
              </Button>
              <Button
                onClick={handleLeaveLobby}
                className="flex-1 bg-red-500 hover:bg-red-600 text-white"
              >
                LEAVE
              </Button>
            </div>
          </Card>
        </div>
      )}
    </>
  );
}

import { useState, useEffect } from "react";
import { useNavigate } from "react-router";
import { ArrowLeft, Navigation, Package, Users, Car } from "lucide-react";
import { Button } from "../ui/button";
import { Card } from "../ui/card";
import { Badge } from "../ui/badge";
import { useAuth } from "../../contexts/AuthContext";
import { supabaseHelpers } from "@/lib/supabase";

// Utility: Forcefully clean corrupted ride data from localStorage
const cleanupStaleRideData = () => {
  try {
    console.log(' CLEANING UP STALE RIDE DATA...');

    // List of ride-related keys to check
    const rideKeys = [
      'trikeserve_active_ride',
      'trikeserve_accepted_rides',
      'trikeserve_share_lobbies'
    ];

    for (const key of rideKeys) {
      const data = localStorage.getItem(key);
      if (!data) continue;

      try {
        if (key === 'trikeserve_active_ride') {
          const ride = JSON.parse(data);
          const activeStatuses = ['accepted', 'on-the-way', 'arrived', 'in-progress'];

          // If ride doesn't have a valid active status, remove it
          if (!ride.status || !activeStatuses.includes(ride.status)) {
            console.log(`️  Removing stale ride (status: ${ride.status || 'none'})`);
            localStorage.removeItem(key);
          }
        } else if (key === 'trikeserve_accepted_rides') {
          const rides = JSON.parse(data);
          const activeStatuses = ['accepted', 'on-the-way', 'arrived', 'in-progress'];

          // Filter out any rides that don't have active status
          const validRides = rides.filter((ride: any) =>
            ride.status && activeStatuses.includes(ride.status)
          );

          if (validRides.length !== rides.length) {
            console.log(`️  Removed ${rides.length - validRides.length} stale accepted rides`);
            if (validRides.length > 0) {
              localStorage.setItem(key, JSON.stringify(validRides));
            } else {
              localStorage.removeItem(key);
            }
          }
        } else if (key === 'trikeserve_share_lobbies') {
          const lobbies = JSON.parse(data);
          const activeStatuses = ['driver-found', 'in-progress'];

          // Filter out lobbies that don't have active status
          const validLobbies = lobbies.filter((lobby: any) =>
            lobby.status && activeStatuses.includes(lobby.status)
          );

          if (validLobbies.length !== lobbies.length) {
            console.log(`️  Removed ${lobbies.length - validLobbies.length} stale lobbies`);
            if (validLobbies.length > 0) {
              localStorage.setItem(key, JSON.stringify(validLobbies));
            } else {
              localStorage.removeItem(key);
            }
          }
        }
      } catch (error) {
        console.error(`Error cleaning key ${key}:`, error);
        // If we can't parse it, remove it
        localStorage.removeItem(key);
      }
    }

    console.log('✅ CLEANUP COMPLETE');
  } catch (error) {
    console.error('Error in cleanupStaleRideData:', error);
  }
};

interface PassengerRequest {
  id: string;
  type: 'delivery' | 'shared' | 'private';
  pickup: string;
  dropoff: string;
  payment: 'COD' | 'PREPAID';
  amount: number;
  foodCost?: number;
  passengers?: number;
  waitingPassengers?: number;
  customerName: string;
  customerPhoto: string;
  distance: string;
  estimatedTime: string;
  pickupAddress?: string;
  dropoffAddress?: string;
  customerId?: string;
  lobbyId?: string; // New field for shared rides
  passengerDetails?: Array<{ // New field for lobby passengers
    id: string;
    name: string;
    emoji: string;
    joinedAt: string;
  }>;
  maxPassengers?: number; // New field for max seats
}

interface LobbyRequest extends PassengerRequest {
  lobbyId: string;
  passengerDetails: Array<{
    id: string;
    name: string;
    emoji: string;
    joinedAt: string;
  }>;
  maxPassengers: number;
}

export default function PassengerRequests() {
  const navigate = useNavigate();
  const { user } = useAuth();
  const [selectedCategory, setSelectedCategory] = useState<'all' | 'shared' | 'private' | 'delivery'>('all');
  const [requests, setRequests] = useState<PassengerRequest[]>([]);

  // Load requests from Supabase on mount and set up polling
  useEffect(() => {
    //  CRITICAL: Clean up any stale ride data on mount
    cleanupStaleRideData();

    const loadRequests = async () => {
      try {
        // Fetch pending ride requests from Supabase
        const { data: rideRequests, error: dbError } = await supabaseHelpers.getRideRequests({
          status: 'pending'
        });

        if (dbError) {
          console.error('❌ Error loading requests from database:', dbError);
          setRequests([]);
          return;
        }

        if (rideRequests && rideRequests.length > 0) {
          // Map database format to component format
          const mappedRequests = rideRequests.map((req: any) => ({
            id: req.id,
            type: req.ride_type || 'private', // Map ride_type to type
            pickup: req.pickup_location,
            dropoff: req.dropoff_location,
            payment: req.payment_method === 'GCASH' ? 'PREPAID' : 'COD',
            amount: req.amount,
            customerName: req.customer_name || 'Customer',
            customerPhoto: '',
            distance: '2.5 km',
            estimatedTime: '7 mins',
            passengers: req.passenger_count || 1,
            customerId: req.customer_id,
            created_at: req.created_at,
          }));

          setRequests(mappedRequests);
          console.log('✅ Loaded passenger requests from database:', mappedRequests);
        } else {
          setRequests([]);
          console.log(' No pending passenger requests in database');
        }
      } catch (error) {
        console.error('❌ Error loading requests:', error);
        setRequests([]);
      }
    };

    // Load initially
    loadRequests();

    // Poll for updates every 3 seconds (fetches from Supabase)
    const interval = setInterval(loadRequests, 3000);

    return () => {
      clearInterval(interval);
    };
  }, []);

  const handleAcceptRequest = (request: PassengerRequest) => {
    //  CRITICAL: Log what request is being accepted
    console.log(' DRIVER ACCEPTING REQUEST ');
    console.log('   Request ID:', request.id);
    console.log('   Request Type:', request.type);
    console.log('   Customer ID:', request.customerId);
    console.log('   Full request object:', request);

    if (!request.id) {
      console.error('❌❌❌ REQUEST HAS NO ID! THIS IS THE BUG! ❌❌❌');
    }
    const activeRideData = localStorage.getItem('trikeserve_active_ride');
    if (activeRideData) {
      try {
        const activeRide = JSON.parse(activeRideData);

        // Only block if the ride is actually active (not completed)
        // Check ride status to determine if it's truly in progress
        const activeStatuses = ['accepted', 'on-the-way', 'arrived', 'in-progress'];
        const isRideActive = activeStatuses.includes(activeRide.status);

        if (!isRideActive) {
          // Ride is completed or invalid, clear it and continue
          localStorage.removeItem('trikeserve_active_ride');
        } else {
          // For shared rides with passenger details, check if all passengers are dropped off
          if (activeRide.passengerDetails && activeRide.passengerDetails.length > 0) {
            const allDroppedOff = activeRide.passengerDetails.every((p: any) => p.status === 'dropped-off');

            if (!allDroppedOff) {
              alert('You already have an active ride. Please complete your current ride before accepting another.');
              return;
            }
            // If all passengers are dropped off, allow accepting new ride
            // The driver just needs to click "Complete Ride" but can start accepting new requests
          } else {
            // For non-shared rides or rides without passenger details, check the status
            alert('You already have an active ride. Please complete your current ride before accepting another.');
            return;
          }
        }
      } catch (error) {
        console.error('Error checking active ride:', error);
      }
    }

    // Check if driver already has an active ride/lobby
    const lobbiesData = localStorage.getItem('trikeserve_share_lobbies');
    if (lobbiesData) {
      try {
        const lobbies = JSON.parse(lobbiesData);
        const driverActiveLobbies = lobbies.filter((lobby: any) => {
          if ((lobby.status === 'driver-found' || lobby.status === 'in-progress') &&
              lobby.driverName === user?.name) {

            // Check if all passengers are dropped off
            if (lobby.passengers && lobby.passengers.length > 0) {
              const allDroppedOff = lobby.passengers.every((p: any) => p.status === 'dropped-off');
              return !allDroppedOff; // Only count as active if not all dropped off
            }
            return true;
          }
          return false;
        });

        if (driverActiveLobbies.length > 0) {
          alert('You already have an active ride. Please complete your current ride before accepting another.');
          return;
        }
      } catch (error) {
        console.error('Error checking driver lobbies:', error);
      }
    }

    // Check if driver has any accepted rides
    const acceptedRidesData = localStorage.getItem('trikeserve_accepted_rides');
    if (acceptedRidesData && user?.id) {
      try {
        const acceptedRides = JSON.parse(acceptedRidesData);
        const driverActiveRides = acceptedRides.filter((ride: any) => 
          ride.driverId === user.id &&
          ride.status &&
          (ride.status === 'accepted' || ride.status === 'in-progress' || ride.status === 'on-the-way' || ride.status === 'arrived')
        );

        if (driverActiveRides.length > 0) {
          console.log('⚠️ Driver has active rides:', driverActiveRides);
          alert('You already have an active ride. Please complete your current ride before accepting another.');
          return;
        }
      } catch (error) {
        console.error('Error checking accepted rides:', error);
      }
    }

    // If it's a shared ride lobby, update lobby status
    if (request.lobbyId) {
      const lobbiesData = localStorage.getItem('trikeserve_share_lobbies');
      if (lobbiesData) {
        try {
          let lobbies = JSON.parse(lobbiesData);
          const lobbyIndex = lobbies.findIndex((l: any) => l.id === request.lobbyId);

          if (lobbyIndex >= 0) {
            // Initialize passenger statuses
            const passengersWithStatus = lobbies[lobbyIndex].passengers.map((p: any) => ({
              ...p,
              status: 'pending'
            }));

            // Update lobby with driver info and passenger statuses
            lobbies[lobbyIndex].status = 'driver-found';
            lobbies[lobbyIndex].driverName = user?.name;
            lobbies[lobbyIndex].driverPlate = user?.todaPlate;
            lobbies[lobbyIndex].driverRating = '4.8';
            lobbies[lobbyIndex].passengers = passengersWithStatus;

            localStorage.setItem('trikeserve_share_lobbies', JSON.stringify(lobbies));

            // Trigger storage event for cross-tab sync
            window.dispatchEvent(new StorageEvent('storage', {
              key: 'trikeserve_share_lobbies',
              newValue: JSON.stringify(lobbies)
            }));

            // Add passenger details to request for acceptedRide
            request.passengerDetails = passengersWithStatus;
          }
        } catch (error) {
          console.error('Error updating lobby:', error);
        }
      }
    }

    // Remove the request from the queue
    const existingRequests = localStorage.getItem('trikeserve_ride_requests');
    let requests: PassengerRequest[] = [];
    if (existingRequests) {
      try {
        requests = JSON.parse(existingRequests);
      } catch (error) {
        console.error('Error parsing requests:', error);
      }
    }

    // Filter out the accepted request
    const updatedRequests = requests.filter(req => req.id !== request.id);
    localStorage.setItem('trikeserve_ride_requests', JSON.stringify(updatedRequests));

    // Create an accepted ride record
    const acceptedRide = {
      ...request,
      driverId: user?.id,
      driverName: user?.name,
      driverPlate: user?.todaPlate,
      driverRating: '4.8',
      status: 'accepted',
      acceptedAt: new Date().toISOString(),
      eta: '5 mins',
    };

    // Store in accepted rides
    const existingAcceptedRides = localStorage.getItem('trikeserve_accepted_rides');
    let acceptedRides = [];
    if (existingAcceptedRides) {
      try {
        acceptedRides = JSON.parse(existingAcceptedRides);
      } catch (error) {
        console.error('Error parsing accepted rides:', error);
      }
    }
    acceptedRides.push(acceptedRide);
    localStorage.setItem('trikeserve_accepted_rides', JSON.stringify(acceptedRides));

    // Navigate to active ride page
    navigate('/rider/active-ride', { state: { acceptedRide } });
  };

  const getServiceIcon = (type: string) => {
    switch(type) {
      case 'delivery': return <Package className="w-5 h-5 text-[#E11D48]" />;
      case 'shared': return <Users className="w-5 h-5 text-[#E11D48]" />;
      case 'private': return <Car className="w-5 h-5 text-[#E11D48]" />;
      default: return <Users className="w-5 h-5 text-[#E11D48]" />;
    }
  };

  const getServiceLabel = (type: string) => {
    switch(type) {
      case 'delivery': return 'DELIVERY';
      case 'shared': return 'RIDE SHARE';
      case 'private': return 'PRIVATE RIDE';
      default: return type.toUpperCase();
    }
  };

  const filteredRequests = requests.filter(request => {
    if (selectedCategory === 'all') return true;
    return request.type === selectedCategory;
  });

  return (
    <div className="min-h-screen bg-[#F8F9FA] relative">
      {/* Header */}
      <div className="bg-white border-b-2 border-[#CBD5E1] px-4 py-3 flex items-center gap-3">
        <Button variant="ghost" size="icon" onClick={() => navigate('/rider')}>
          <ArrowLeft className="w-5 h-5" />
        </Button>
        <div className="flex-1">
          <h1 className="text-xl font-extrabold text-[#E11D48]" style={{ letterSpacing: '-0.02em' }}>
            Passenger Requests
          </h1>
          <p className="text-xs text-[#64748B]">{requests.length} customers looking for service</p>
        </div>
      </div>

      {/* Main Content */}
      <div className="p-4 space-y-3">
        <div className="bg-teal-50 border border-teal-200 rounded-lg p-3 mb-4">
          <p className="text-sm text-teal-900">
            <span className="font-bold">{requests.length} passengers</span> are currently looking for tricycle service in your area
          </p>
          <p className="text-xs text-teal-700 mt-1">
             You can view requests anytime, even when offline
          </p>
        </div>

        <div className="flex gap-2 mb-4 overflow-x-auto scrollbar-hide">
          <button
            onClick={() => setSelectedCategory('all')}
            className={`px-4 py-2 rounded-full text-sm font-medium whitespace-nowrap transition-all flex-shrink-0 ${
              selectedCategory === 'all'
                ? 'bg-[#E11D48] text-white'
                : 'bg-[#F1F5F9] text-[#64748B] hover:bg-[#E2E8F0]'
            }`}
          >
            All
          </button>
          <button
            onClick={() => setSelectedCategory('shared')}
            className={`px-4 py-2 rounded-full text-sm font-medium whitespace-nowrap transition-all flex-shrink-0 ${
              selectedCategory === 'shared'
                ? 'bg-[#E11D48] text-white'
                : 'bg-[#F1F5F9] text-[#64748B] hover:bg-[#E2E8F0]'
            }`}
          >
            Share Ride
          </button>
          <button
            onClick={() => setSelectedCategory('private')}
            className={`px-4 py-2 rounded-full text-sm font-medium whitespace-nowrap transition-all flex-shrink-0 ${
              selectedCategory === 'private'
                ? 'bg-[#E11D48] text-white'
                : 'bg-[#F1F5F9] text-[#64748B] hover:bg-[#E2E8F0]'
            }`}
          >
            Private Ride
          </button>
          <button
            onClick={() => setSelectedCategory('delivery')}
            className={`px-4 py-2 rounded-full text-sm font-medium whitespace-nowrap transition-all flex-shrink-0 ${
              selectedCategory === 'delivery'
                ? 'bg-[#E11D48] text-white'
                : 'bg-[#F1F5F9] text-[#64748B] hover:bg-[#E2E8F0]'
            }`}
          >
            Delivery
          </button>
        </div>

        {filteredRequests.map((request) => (
          <Card key={request.id} className="p-4 bg-white border-2 border-[#CBD5E1] hover:border-[#E11D48] transition-colors">
            {/* Shared Ride Lobby Display */}
            {request.lobbyId && request.passengerDetails && request.passengerDetails.length > 0 ? (
              <div className="flex flex-col gap-3">
                {/* Lobby Header */}
                <div className="flex items-start justify-between">
                  <div>
                    <div className="flex items-center gap-2 mb-2">
                      <Badge className="bg-purple-500">
                         SHARED RIDE LOBBY
                      </Badge>
                      <Badge variant="outline" className="border-[#E11D48] text-[#E11D48]">
                        {request.passengerDetails.length}/{request.maxPassengers || 3} SEATS
                      </Badge>
                    </div>
                    <Badge variant="outline" className={request.payment === 'COD' ? 'border-orange-500 text-orange-500' : 'border-green-500 text-green-500'}>
                      {request.payment}
                    </Badge>
                  </div>
                  <div className="text-right">
                    <p className="font-bold text-2xl text-[#E11D48]">₱{request.amount}</p>
                    <p className="text-xs text-[#64748B]">{request.distance}</p>
                    <p className="text-xs font-semibold text-purple-600">
                      ₱{Math.round(request.amount / (request.passengerDetails.length || 1))} per seat
                    </p>
                  </div>
                </div>

                {/* Passengers in Lobby */}
                <div className="bg-gradient-to-r from-purple-50 to-pink-50 border-2 border-purple-200 rounded-xl p-3">
                  <p className="text-xs font-bold text-purple-700 uppercase tracking-wide mb-2">Passengers Waiting</p>
                  <div className="space-y-2">
                    {request.passengerDetails.map((passenger, index) => (
                      <div key={passenger.id} className="flex items-start gap-2 bg-white rounded-lg px-3 py-2 border border-purple-100">
                        <span className="text-2xl flex-shrink-0">{passenger.emoji}</span>
                        <div className="flex-1 min-w-0">
                          <div className="flex items-center gap-2 flex-wrap">
                            <p className="text-sm font-semibold text-[#121212]">{passenger.name}</p>
                            {index === 0 && (
                              <Badge className="bg-purple-500 text-white text-[9px] px-1 py-0">HOST</Badge>
                            )}
                          </div>
                          {(passenger as any).pickup && (
                            <div className="mt-1">
                              <p className="text-xs text-[#64748B]">Pickup: {(passenger as any).pickup}</p>
                              {(passenger as any).pickupAddress && (
                                <p className="text-[10px] text-[#94A3B8]">{(passenger as any).pickupAddress}</p>
                              )}
                            </div>
                          )}
                        </div>
                      </div>
                    ))}
                  </div>
                </div>

                {/* Route Info */}
                <div className="space-y-2 text-sm">
                  <div className="flex gap-2">
                    <Navigation className="w-4 h-4 text-[#E11D48] flex-shrink-0 mt-0.5" />
                    <div className="flex-1">
                      <p className="text-xs text-[#64748B]">Pickup</p>
                      <p className="font-semibold text-[#121212]">{request.pickup}</p>
                      {request.pickupAddress && (
                        <p className="text-xs text-[#64748B] mt-0.5">{request.pickupAddress}</p>
                      )}
                    </div>
                  </div>
                  <div className="flex gap-2">
                    <Navigation className="w-4 h-4 text-green-600 flex-shrink-0 mt-0.5" />
                    <div className="flex-1">
                      <p className="text-xs text-[#64748B]">Drop-off</p>
                      <p className="font-semibold text-[#121212]">{request.dropoff}</p>
                      {request.dropoffAddress && (
                        <p className="text-xs text-[#64748B] mt-0.5">{request.dropoffAddress}</p>
                      )}
                    </div>
                  </div>
                </div>

                {/* Trip Details */}
                <div className="flex gap-2">
                  <div className="flex-1 bg-gray-50 rounded p-2">
                    <p className="text-xs text-[#64748B]">Distance</p>
                    <p className="text-sm font-semibold text-[#121212]">{request.distance}</p>
                  </div>
                  <div className="flex-1 bg-gray-50 rounded p-2">
                    <p className="text-xs text-[#64748B]">Est. Time</p>
                    <p className="text-sm font-semibold text-[#121212]">{request.estimatedTime}</p>
                  </div>
                </div>

                {/* Lobby Full Indicator */}
                {request.passengerDetails.length === (request.maxPassengers || 3) && (
                  <div className="bg-green-50 border border-green-200 rounded-lg p-2">
                    <p className="text-xs text-green-700 font-semibold text-center">
                       Lobby Full - Priority Request!
                    </p>
                  </div>
                )}

                <Button
                  onClick={() => handleAcceptRequest(request)}
                  className="w-full bg-[#E11D48] hover:bg-[#BE123C] uppercase"
                >
                  Accept Lobby ({request.passengerDetails.length} Passengers)
                </Button>
              </div>
            ) : (
              /* Regular Request Display */
              <div className="flex items-start gap-3 mb-3">
                <div className="text-4xl">{request.customerPhoto}</div>
                <div className="flex-1">
                  <div className="flex items-start justify-between mb-2">
                    <div>
                      <p className="font-bold text-[#121212]">{request.customerName}</p>
                      <div className="flex items-center gap-2 mt-1">
                        <Badge className="bg-[#E11D48]">
                          {getServiceLabel(request.type)}
                        </Badge>
                        <Badge variant="outline" className={request.payment === 'COD' ? 'border-orange-500 text-orange-500' : 'border-green-500 text-green-500'}>
                          {request.payment}
                        </Badge>
                        {request.passengers && request.passengers > 1 && (
                          <Badge variant="outline" className="border-blue-500 text-blue-500">
                             {request.passengers} PAX
                          </Badge>
                        )}
                      </div>
                    </div>
                    <div className="text-right">
                      <p className="font-bold text-xl text-[#E11D48]">₱{request.amount}</p>
                      <p className="text-xs text-[#64748B]">{request.distance}</p>
                    </div>
                  </div>

                  <div className="space-y-2 mb-3 text-sm">
                    <div className="flex gap-2">
                      <Navigation className="w-4 h-4 text-[#E11D48] flex-shrink-0 mt-0.5" />
                      <div className="flex-1">
                        <p className="text-xs text-[#64748B]">Pickup</p>
                        <p className="font-semibold text-[#121212]">{request.pickup}</p>
                        {request.pickupAddress && (
                          <p className="text-xs text-[#64748B] mt-0.5">{request.pickupAddress}</p>
                        )}
                      </div>
                    </div>
                    <div className="flex gap-2">
                      <Navigation className="w-4 h-4 text-green-600 flex-shrink-0 mt-0.5" />
                      <div className="flex-1">
                        <p className="text-xs text-[#64748B]">Drop-off</p>
                        <p className="font-semibold text-[#121212]">{request.dropoff}</p>
                        {request.dropoffAddress && (
                          <p className="text-xs text-[#64748B] mt-0.5">{request.dropoffAddress}</p>
                        )}
                      </div>
                    </div>
                  </div>

                  {request.waitingPassengers && (
                    <p className="text-sm text-[#E11D48] font-semibold mb-2">
                       {request.waitingPassengers} passenger(s) waiting
                    </p>
                  )}

                  {request.type === 'delivery' && request.payment === 'COD' && (
                    <div className="bg-orange-50 border border-orange-200 rounded-lg p-2 mb-3">
                      <p className="text-xs text-orange-900">
                        <span className="font-semibold">⚠️ Pay Restaurant First:</span> ₱{request.foodCost}
                      </p>
                    </div>
                  )}

                  <div className="flex gap-2 mb-2">
                    <div className="flex-1 bg-gray-50 rounded p-2">
                      <p className="text-xs text-[#64748B]">Distance</p>
                      <p className="text-sm font-semibold text-[#121212]">{request.distance}</p>
                    </div>
                    <div className="flex-1 bg-gray-50 rounded p-2">
                      <p className="text-xs text-[#64748B]">Est. Time</p>
                      <p className="text-sm font-semibold text-[#121212]">{request.estimatedTime}</p>
                    </div>
                  </div>

                  <Button
                    onClick={() => handleAcceptRequest(request)}
                    className="w-full bg-[#E11D48] hover:bg-[#BE123C] uppercase"
                  >
                    Accept Request
                  </Button>
                </div>
              </div>
            )}
          </Card>
        ))}

        {/* Empty State */}
        {filteredRequests.length === 0 && (
          <div className="text-center py-12">
            <div className="w-20 h-20 bg-[#F1F5F9] rounded-full flex items-center justify-center mx-auto mb-4">
              <Users className="w-10 h-10 text-[#94A3B8]" />
            </div>
            <h3 className="text-lg font-bold text-[#121212] mb-2">No passenger requests</h3>
            <p className="text-sm text-[#64748B]">
              {selectedCategory === 'all' 
                ? 'Waiting for customers to request rides...'
                : `No ${selectedCategory} ride requests at the moment`}
            </p>
          </div>
        )}
      </div>
    </div>
  );
}

import { useState, useEffect } from "react";
import { useNavigate } from "react-router";
import { ArrowLeft, Navigation, Package, Users, Car } from "lucide-react";
import { Button } from "../ui/button";
import { Card } from "../ui/card";
import { Badge } from "../ui/badge";
import { useAuth } from "../../contexts/AuthContext";
import { supabaseHelpers } from "@/lib/supabase";

// Utility: Forcefully clean corrupted ride data from localStorage
const cleanupStaleRideData = () => {
  try {
    console.log(' CLEANING UP STALE RIDE DATA...');

    // List of ride-related keys to check
    const rideKeys = [
      'trikeserve_active_ride',
      'trikeserve_accepted_rides'
    ];

    for (const key of rideKeys) {
      const data = localStorage.getItem(key);
      if (!data) continue;

      try {
        if (key === 'trikeserve_active_ride') {
          const ride = JSON.parse(data);
          const activeStatuses = ['accepted', 'on-the-way', 'arrived', 'in-progress'];

          // If ride doesn't have a valid active status, remove it
          if (!ride.status || !activeStatuses.includes(ride.status)) {
            console.log(`️  Removing stale ride (status: ${ride.status || 'none'})`);
            localStorage.removeItem(key);
          }
        } else if (key === 'trikeserve_accepted_rides') {
          const rides = JSON.parse(data);
          const activeStatuses = ['accepted', 'on-the-way', 'arrived', 'in-progress'];

          // Filter out any rides that don't have active status
          const validRides = rides.filter((ride: any) =>
            ride.status && activeStatuses.includes(ride.status)
          );

          if (validRides.length !== rides.length) {
            console.log(`️  Removed ${rides.length - validRides.length} stale accepted rides`);
            if (validRides.length > 0) {
              localStorage.setItem(key, JSON.stringify(validRides));
            } else {
              localStorage.removeItem(key);
            }
          }
        }
      } catch (error) {
        console.error(`Error cleaning key ${key}:`, error);
        // If we can't parse it, remove it
        localStorage.removeItem(key);
      }
    }

    console.log('✅ CLEANUP COMPLETE');
  } catch (error) {
    console.error('Error in cleanupStaleRideData:', error);
  }
};

interface PassengerRequest {
  id: string;
  type: 'delivery' | 'shared' | 'private';
  pickup: string;
  dropoff: string;
  payment: 'COD' | 'PREPAID';
  amount: number;
  foodCost?: number;
  passengers?: number;
  waitingPassengers?: number;
  customerName: string;
  customerPhoto: string;
  distance: string;
  estimatedTime: string;
  pickupAddress?: string;
  dropoffAddress?: string;
  customerId?: string;
  lobbyId?: string; // New field for shared rides
  passengerDetails?: Array<{ // New field for lobby passengers
    id: string;
    name: string;
    emoji: string;
    joinedAt: string;
  }>;
  maxPassengers?: number; // New field for max seats
}

interface LobbyRequest extends PassengerRequest {
  lobbyId: string;
  passengerDetails: Array<{
    id: string;
    name: string;
    emoji: string;
    joinedAt: string;
  }>;
  maxPassengers: number;
}

export default function PassengerRequests() {
  const navigate = useNavigate();
  const { user } = useAuth();
  const [selectedCategory, setSelectedCategory] = useState<'all' | 'shared' | 'private' | 'delivery'>('all');
  const [requests, setRequests] = useState<PassengerRequest[]>([]);

  // Load requests from Supabase on mount and set up polling
  useEffect(() => {
    //  CRITICAL: Clean up any stale ride data on mount
    cleanupStaleRideData();

    const loadRequests = async () => {
      try {
        // Fetch pending ride requests from Supabase
        const { data: rideRequests, error: dbError } = await supabaseHelpers.getRideRequests({
          status: 'pending'
        });

        // Fetch waiting shared lobbies from Supabase
        const { data: waitingLobbies, error: lobbyError } = await supabaseHelpers.getWaitingLobbiesForDriver();

        if (dbError) {
          console.error('❌ Error loading requests from database:', dbError);
        }

        if (lobbyError) {
          console.error('❌ Error loading waiting lobbies from database:', lobbyError);
        }

        const mappedRequests = (rideRequests || []).map((req: any) => ({
            id: req.id,
            type: req.ride_type || 'private', // Map ride_type to type
            pickup: req.pickup_location,
            dropoff: req.dropoff_location,
            payment: req.payment_method === 'GCASH' ? 'PREPAID' : 'COD',
            amount: req.amount,
            customerName: req.customer_name || 'Customer',
            customerPhoto: '',
            distance: '2.5 km',
            estimatedTime: '7 mins',
            passengers: req.passenger_count || 1,
            customerId: req.customer_id,
            created_at: req.created_at,
          }));

        const mappedLobbies = (waitingLobbies || []).map((lobby: any) => {
          const passengers = Array.isArray(lobby.passengers_json) ? lobby.passengers_json : [];
          return {
            id: `lobby_${lobby.id}`,
            type: 'shared',
            pickup: lobby.pickup_location,
            dropoff: lobby.dropoff_location,
            pickupAddress: lobby.pickup_address,
            dropoffAddress: lobby.dropoff_address,
            payment: 'PREPAID',
            amount: Number(lobby.price_per_seat || 15) * passengers.length,
            passengers: passengers.length,
            maxPassengers: Number(lobby.max_seats || 3),
            customerName: passengers.length > 1 ? `${passengers.length} Passengers` : (passengers[0]?.name || 'Customer'),
            customerPhoto: '',
            distance: '2.5 km',
            estimatedTime: '7 mins',
            customerId: lobby.customer_id,
            lobbyId: lobby.id,
            passengerDetails: passengers,
            created_at: lobby.created_at,
          } as PassengerRequest;
        });

        const mergedRequests = [...mappedRequests, ...mappedLobbies];
        setRequests(mergedRequests);
        console.log('✅ Loaded passenger + lobby requests from database:', mergedRequests);
      } catch (error) {
        console.error('❌ Error loading requests:', error);
        setRequests([]);
      }
    };

    // Load initially
    loadRequests();

    // Poll for updates every 3 seconds (fetches from Supabase)
    const interval = setInterval(loadRequests, 3000);

    return () => {
      clearInterval(interval);
    };
  }, []);

  const handleAcceptRequest = async (request: PassengerRequest) => {
    //  CRITICAL: Log what request is being accepted
    console.log(' DRIVER ACCEPTING REQUEST ');
    console.log('   Request ID:', request.id);
    console.log('   Request Type:', request.type);
    console.log('   Customer ID:', request.customerId);
    console.log('   Full request object:', request);

    if (!request.id) {
      console.error('❌❌❌ REQUEST HAS NO ID! THIS IS THE BUG! ❌❌❌');
    }

    if (!user?.id) {
      alert('You must be logged in as a driver to accept requests.');
      return;
    }
    const activeRideData = localStorage.getItem('trikeserve_active_ride');
    if (activeRideData) {
      try {
        const activeRide = JSON.parse(activeRideData);

        // Only block if the ride is actually active (not completed)
        // Check ride status to determine if it's truly in progress
        const activeStatuses = ['accepted', 'on-the-way', 'arrived', 'in-progress'];
        const isRideActive = activeStatuses.includes(activeRide.status);

        if (!isRideActive) {
          // Ride is completed or invalid, clear it and continue
          localStorage.removeItem('trikeserve_active_ride');
        } else {
          // For shared rides with passenger details, check if all passengers are dropped off
          if (activeRide.passengerDetails && activeRide.passengerDetails.length > 0) {
            const allDroppedOff = activeRide.passengerDetails.every((p: any) => p.status === 'dropped-off');

            if (!allDroppedOff) {
              alert('You already have an active ride. Please complete your current ride before accepting another.');
              return;
            }
            // If all passengers are dropped off, allow accepting new ride
            // The driver just needs to click "Complete Ride" but can start accepting new requests
          } else {
            // For non-shared rides or rides without passenger details, check the status
            alert('You already have an active ride. Please complete your current ride before accepting another.');
            return;
          }
        }
      } catch (error) {
        console.error('Error checking active ride:', error);
      }
    }

    // Check if driver already has an active shared lobby in Supabase
    if (user?.id) {
      try {
        const { data: allLobbies, error: lobbiesError } = await supabaseHelpers.getLobbies();
        if (!lobbiesError && allLobbies) {
          const driverActiveLobbies = allLobbies.filter((lobby: any) =>
            lobby.driver_id === user.id &&
            (lobby.status === 'driver_found' || lobby.status === 'in_progress')
          );

          if (driverActiveLobbies.length > 0) {
            alert('You already have an active ride. Please complete your current ride before accepting another.');
            return;
          }
        }
      } catch (error) {
        console.error('Error checking driver lobbies:', error);
      }
    }

    // Check if driver has any accepted rides
    const acceptedRidesData = localStorage.getItem('trikeserve_accepted_rides');
    if (acceptedRidesData && user?.id) {
      try {
        const acceptedRides = JSON.parse(acceptedRidesData);
        const driverActiveRides = acceptedRides.filter((ride: any) => 
          ride.driverId === user.id &&
          ride.status &&
          (ride.status === 'accepted' || ride.status === 'in-progress' || ride.status === 'on-the-way' || ride.status === 'arrived')
        );

        if (driverActiveRides.length > 0) {
          console.log('⚠️ Driver has active rides:', driverActiveRides);
          alert('You already have an active ride. Please complete your current ride before accepting another.');
          return;
        }
      } catch (error) {
        console.error('Error checking accepted rides:', error);
      }
    }

    // If it's a shared ride lobby, update lobby status in Supabase
    if (request.lobbyId) {
      try {
        const { data: updatedLobby, error: acceptError } = await supabaseHelpers.acceptLobbyAsDriver(
          request.lobbyId,
          user?.id || '',
          user?.name || 'Driver',
          user?.todaPlate,
          '4.8'
        );

        if (acceptError) {
          console.error('Error accepting shared lobby:', acceptError);
          alert('Failed to accept shared ride lobby. Please try again.');
          return;
        }

        request.passengerDetails = Array.isArray(updatedLobby?.passengers_json) ? updatedLobby.passengers_json : [];
      } catch (error) {
        console.error('Error updating lobby:', error);
        alert('Failed to update shared ride lobby. Please try again.');
        return;
      }
    }

    // Create an accepted ride record
    const acceptedRide = {
      ...request,
      driverId: user?.id,
      driverName: user?.name,
      driverPlate: user?.todaPlate,
      driverRating: '4.8',
      status: 'accepted',
      acceptedAt: new Date().toISOString(),
      eta: '5 mins',
    };

    // Store in accepted rides
    const existingAcceptedRides = localStorage.getItem('trikeserve_accepted_rides');
    let acceptedRides = [];
    if (existingAcceptedRides) {
      try {
        acceptedRides = JSON.parse(existingAcceptedRides);
      } catch (error) {
        console.error('Error parsing accepted rides:', error);
      }
    }
    acceptedRides.push(acceptedRide);
    localStorage.setItem('trikeserve_accepted_rides', JSON.stringify(acceptedRides));

    // Navigate to active ride page
    navigate('/rider/active-ride', { state: { acceptedRide } });
  };

  const getServiceIcon = (type: string) => {
    switch(type) {
      case 'delivery': return <Package className="w-5 h-5 text-[#E11D48]" />;
      case 'shared': return <Users className="w-5 h-5 text-[#E11D48]" />;
      case 'private': return <Car className="w-5 h-5 text-[#E11D48]" />;
      default: return <Users className="w-5 h-5 text-[#E11D48]" />;
    }
  };

  const getServiceLabel = (type: string) => {
    switch(type) {
      case 'delivery': return 'DELIVERY';
      case 'shared': return 'RIDE SHARE';
      case 'private': return 'PRIVATE RIDE';
      default: return type.toUpperCase();
    }
  };

  const filteredRequests = requests.filter(request => {
    if (selectedCategory === 'all') return true;
    return request.type === selectedCategory;
  });

  return (
    <div className="min-h-screen bg-[#F8F9FA] relative">
      {/* Header */}
      <div className="bg-white border-b-2 border-[#CBD5E1] px-4 py-3 flex items-center gap-3">
        <Button variant="ghost" size="icon" onClick={() => navigate('/rider')}>
          <ArrowLeft className="w-5 h-5" />
        </Button>
        <div className="flex-1">
          <h1 className="text-xl font-extrabold text-[#E11D48]" style={{ letterSpacing: '-0.02em' }}>
            Passenger Requests
          </h1>
          <p className="text-xs text-[#64748B]">{requests.length} customers looking for service</p>
        </div>
      </div>

      {/* Main Content */}
      <div className="p-4 space-y-3">
        <div className="bg-teal-50 border border-teal-200 rounded-lg p-3 mb-4">
          <p className="text-sm text-teal-900">
            <span className="font-bold">{requests.length} passengers</span> are currently looking for tricycle service in your area
          </p>
          <p className="text-xs text-teal-700 mt-1">
             You can view requests anytime, even when offline
          </p>
        </div>

        <div className="flex gap-2 mb-4 overflow-x-auto scrollbar-hide">
          <button
            onClick={() => setSelectedCategory('all')}
            className={`px-4 py-2 rounded-full text-sm font-medium whitespace-nowrap transition-all flex-shrink-0 ${
              selectedCategory === 'all'
                ? 'bg-[#E11D48] text-white'
                : 'bg-[#F1F5F9] text-[#64748B] hover:bg-[#E2E8F0]'
            }`}
          >
            All
          </button>
          <button
            onClick={() => setSelectedCategory('shared')}
            className={`px-4 py-2 rounded-full text-sm font-medium whitespace-nowrap transition-all flex-shrink-0 ${
              selectedCategory === 'shared'
                ? 'bg-[#E11D48] text-white'
                : 'bg-[#F1F5F9] text-[#64748B] hover:bg-[#E2E8F0]'
            }`}
          >
            Share Ride
          </button>
          <button
            onClick={() => setSelectedCategory('private')}
            className={`px-4 py-2 rounded-full text-sm font-medium whitespace-nowrap transition-all flex-shrink-0 ${
              selectedCategory === 'private'
                ? 'bg-[#E11D48] text-white'
                : 'bg-[#F1F5F9] text-[#64748B] hover:bg-[#E2E8F0]'
            }`}
          >
            Private Ride
          </button>
          <button
            onClick={() => setSelectedCategory('delivery')}
            className={`px-4 py-2 rounded-full text-sm font-medium whitespace-nowrap transition-all flex-shrink-0 ${
              selectedCategory === 'delivery'
                ? 'bg-[#E11D48] text-white'
                : 'bg-[#F1F5F9] text-[#64748B] hover:bg-[#E2E8F0]'
            }`}
          >
            Delivery
          </button>
        </div>

        {filteredRequests.map((request) => (
          <Card key={request.id} className="p-4 bg-white border-2 border-[#CBD5E1] hover:border-[#E11D48] transition-colors">
            {/* Shared Ride Lobby Display */}
            {request.lobbyId && request.passengerDetails && request.passengerDetails.length > 0 ? (
              <div className="flex flex-col gap-3">
                {/* Lobby Header */}
                <div className="flex items-start justify-between">
                  <div>
                    <div className="flex items-center gap-2 mb-2">
                      <Badge className="bg-purple-500">
                         SHARED RIDE LOBBY
                      </Badge>
                      <Badge variant="outline" className="border-[#E11D48] text-[#E11D48]">
                        {request.passengerDetails.length}/{request.maxPassengers || 3} SEATS
                      </Badge>
                    </div>
                    <Badge variant="outline" className={request.payment === 'COD' ? 'border-orange-500 text-orange-500' : 'border-green-500 text-green-500'}>
                      {request.payment}
                    </Badge>
                  </div>
                  <div className="text-right">
                    <p className="font-bold text-2xl text-[#E11D48]">₱{request.amount}</p>
                    <p className="text-xs text-[#64748B]">{request.distance}</p>
                    <p className="text-xs font-semibold text-purple-600">
                      ₱{Math.round(request.amount / (request.passengerDetails.length || 1))} per seat
                    </p>
                  </div>
                </div>

                {/* Passengers in Lobby */}
                <div className="bg-gradient-to-r from-purple-50 to-pink-50 border-2 border-purple-200 rounded-xl p-3">
                  <p className="text-xs font-bold text-purple-700 uppercase tracking-wide mb-2">Passengers Waiting</p>
                  <div className="space-y-2">
                    {request.passengerDetails.map((passenger, index) => (
                      <div key={passenger.id} className="flex items-start gap-2 bg-white rounded-lg px-3 py-2 border border-purple-100">
                        <span className="text-2xl flex-shrink-0">{passenger.emoji}</span>
                        <div className="flex-1 min-w-0">
                          <div className="flex items-center gap-2 flex-wrap">
                            <p className="text-sm font-semibold text-[#121212]">{passenger.name}</p>
                            {index === 0 && (
                              <Badge className="bg-purple-500 text-white text-[9px] px-1 py-0">HOST</Badge>
                            )}
                          </div>
                          {(passenger as any).pickup && (
                            <div className="mt-1">
                              <p className="text-xs text-[#64748B]">Pickup: {(passenger as any).pickup}</p>
                              {(passenger as any).pickupAddress && (
                                <p className="text-[10px] text-[#94A3B8]">{(passenger as any).pickupAddress}</p>
                              )}
                            </div>
                          )}
                        </div>
                      </div>
                    ))}
                  </div>
                </div>

                {/* Route Info */}
                <div className="space-y-2 text-sm">
                  <div className="flex gap-2">
                    <Navigation className="w-4 h-4 text-[#E11D48] flex-shrink-0 mt-0.5" />
                    <div className="flex-1">
                      <p className="text-xs text-[#64748B]">Pickup</p>
                      <p className="font-semibold text-[#121212]">{request.pickup}</p>
                      {request.pickupAddress && (
                        <p className="text-xs text-[#64748B] mt-0.5">{request.pickupAddress}</p>
                      )}
                    </div>
                  </div>
                  <div className="flex gap-2">
                    <Navigation className="w-4 h-4 text-green-600 flex-shrink-0 mt-0.5" />
                    <div className="flex-1">
                      <p className="text-xs text-[#64748B]">Drop-off</p>
                      <p className="font-semibold text-[#121212]">{request.dropoff}</p>
                      {request.dropoffAddress && (
                        <p className="text-xs text-[#64748B] mt-0.5">{request.dropoffAddress}</p>
                      )}
                    </div>
                  </div>
                </div>

                {/* Trip Details */}
                <div className="flex gap-2">
                  <div className="flex-1 bg-gray-50 rounded p-2">
                    <p className="text-xs text-[#64748B]">Distance</p>
                    <p className="text-sm font-semibold text-[#121212]">{request.distance}</p>
                  </div>
                  <div className="flex-1 bg-gray-50 rounded p-2">
                    <p className="text-xs text-[#64748B]">Est. Time</p>
                    <p className="text-sm font-semibold text-[#121212]">{request.estimatedTime}</p>
                  </div>
                </div>

                {/* Lobby Full Indicator */}
                {request.passengerDetails.length === (request.maxPassengers || 3) && (
                  <div className="bg-green-50 border border-green-200 rounded-lg p-2">
                    <p className="text-xs text-green-700 font-semibold text-center">
                       Lobby Full - Priority Request!
                    </p>
                  </div>
                )}

                <Button
                  onClick={() => handleAcceptRequest(request)}
                  className="w-full bg-[#E11D48] hover:bg-[#BE123C] uppercase"
                >
                  Accept Lobby ({request.passengerDetails.length} Passengers)
                </Button>
              </div>
            ) : (
              /* Regular Request Display */
              <div className="flex items-start gap-3 mb-3">
                <div className="text-4xl">{request.customerPhoto}</div>
                <div className="flex-1">
                  <div className="flex items-start justify-between mb-2">
                    <div>
                      <p className="font-bold text-[#121212]">{request.customerName}</p>
                      <div className="flex items-center gap-2 mt-1">
                        <Badge className="bg-[#E11D48]">
                          {getServiceLabel(request.type)}
                        </Badge>
                        <Badge variant="outline" className={request.payment === 'COD' ? 'border-orange-500 text-orange-500' : 'border-green-500 text-green-500'}>
                          {request.payment}
                        </Badge>
                        {request.passengers && request.passengers > 1 && (
                          <Badge variant="outline" className="border-blue-500 text-blue-500">
                             {request.passengers} PAX
                          </Badge>
                        )}
                      </div>
                    </div>
                    <div className="text-right">
                      <p className="font-bold text-xl text-[#E11D48]">₱{request.amount}</p>
                      <p className="text-xs text-[#64748B]">{request.distance}</p>
                    </div>
                  </div>

                  <div className="space-y-2 mb-3 text-sm">
                    <div className="flex gap-2">
                      <Navigation className="w-4 h-4 text-[#E11D48] flex-shrink-0 mt-0.5" />
                      <div className="flex-1">
                        <p className="text-xs text-[#64748B]">Pickup</p>
                        <p className="font-semibold text-[#121212]">{request.pickup}</p>
                        {request.pickupAddress && (
                          <p className="text-xs text-[#64748B] mt-0.5">{request.pickupAddress}</p>
                        )}
                      </div>
                    </div>
                    <div className="flex gap-2">
                      <Navigation className="w-4 h-4 text-green-600 flex-shrink-0 mt-0.5" />
                      <div className="flex-1">
                        <p className="text-xs text-[#64748B]">Drop-off</p>
                        <p className="font-semibold text-[#121212]">{request.dropoff}</p>
                        {request.dropoffAddress && (
                          <p className="text-xs text-[#64748B] mt-0.5">{request.dropoffAddress}</p>
                        )}
                      </div>
                    </div>
                  </div>

                  {request.waitingPassengers && (
                    <p className="text-sm text-[#E11D48] font-semibold mb-2">
                       {request.waitingPassengers} passenger(s) waiting
                    </p>
                  )}

                  {request.type === 'delivery' && request.payment === 'COD' && (
                    <div className="bg-orange-50 border border-orange-200 rounded-lg p-2 mb-3">
                      <p className="text-xs text-orange-900">
                        <span className="font-semibold">⚠️ Pay Restaurant First:</span> ₱{request.foodCost}
                      </p>
                    </div>
                  )}

                  <div className="flex gap-2 mb-2">
                    <div className="flex-1 bg-gray-50 rounded p-2">
                      <p className="text-xs text-[#64748B]">Distance</p>
                      <p className="text-sm font-semibold text-[#121212]">{request.distance}</p>
                    </div>
                    <div className="flex-1 bg-gray-50 rounded p-2">
                      <p className="text-xs text-[#64748B]">Est. Time</p>
                      <p className="text-sm font-semibold text-[#121212]">{request.estimatedTime}</p>
                    </div>
                  </div>

                  <Button
                    onClick={() => handleAcceptRequest(request)}
                    className="w-full bg-[#E11D48] hover:bg-[#BE123C] uppercase"
                  >
                    Accept Request
                  </Button>
                </div>
              </div>
            )}
          </Card>
        ))}

        {/* Empty State */}
        {filteredRequests.length === 0 && (
          <div className="text-center py-12">
            <div className="w-20 h-20 bg-[#F1F5F9] rounded-full flex items-center justify-center mx-auto mb-4">
              <Users className="w-10 h-10 text-[#94A3B8]" />
            </div>
            <h3 className="text-lg font-bold text-[#121212] mb-2">No passenger requests</h3>
            <p className="text-sm text-[#64748B]">
              {selectedCategory === 'all' 
                ? 'Waiting for customers to request rides...'
                : `No ${selectedCategory} ride requests at the moment`}
            </p>
          </div>
        )}
      </div>
    </div>
  );
}

import { createClient } from '@supabase/supabase-js';

// Initialize Supabase client
const supabaseUrl = import.meta.env.VITE_SUPABASE_URL;
const supabaseAnonKey = import.meta.env.VITE_SUPABASE_ANON_KEY;

console.log('[Supabase Init] Checking environment variables...');
console.log('[Supabase Init] VITE_SUPABASE_URL:', supabaseUrl ? '✅ Set' : '❌ Missing');
console.log('[Supabase Init] VITE_SUPABASE_ANON_KEY:', supabaseAnonKey ? '✅ Set' : '❌ Missing');

// Check if credentials are configured
if (!supabaseUrl || !supabaseAnonKey) {
  const missing = [];
  if (!supabaseUrl) missing.push('VITE_SUPABASE_URL');
  if (!supabaseAnonKey) missing.push('VITE_SUPABASE_ANON_KEY');

  const errorMsg =
    `\n\n❌ SUPABASE CONFIGURATION ERROR\n` +
    `━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n` +
    `Missing environment variables: ${missing.join(', ')}\n\n` +
    `How to fix:\n` +
    `1. Open the file: .env.local (in project root)\n` +
    `2. Make sure it contains:\n` +
    `   VITE_SUPABASE_URL=https://azmzuucnfqqymnunntmw.supabase.co\n` +
    `   VITE_SUPABASE_ANON_KEY=your_actual_key_here\n\n` +
    `3. Get the key from: Supabase Dashboard → Settings → API\n` +
    `4. STOP the dev server (Ctrl+C)\n` +
    `5. DELETE the .vite cache folder in node_modules\n` +
    `6. RESTART with: npm run dev\n` +
    `━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n\n`;

  console.error(errorMsg);
  throw new Error(`Missing Supabase credentials: ${missing.join(', ')}`);
}

console.log('[Supabase Init] ✅ All credentials loaded successfully');

export const supabase = createClient(
  supabaseUrl,
  supabaseAnonKey
);

// Helper functions for common operations
export const supabaseHelpers = {
  // User operations
  async getUserById(userId: string) {
    const { data, error } = await supabase
      .from('users')
      .select('*')
      .eq('id', userId)
      .single();
    return { data, error };
  },

  async getUserByEmail(email: string) {
    const { data, error } = await supabase
      .from('users')
      .select('*')
      .eq('email', email)
      .single();
    return { data, error };
  },

  async createUser(user: any) {
    const { data, error } = await supabase
      .from('users')
      .insert([user])
      .select()
      .single();
    return { data, error };
  },

  async updateUser(userId: string, updates: any) {
    const { data, error } = await supabase
      .from('users')
      .update(updates)
      .eq('id', userId)
      .select()
      .single();
    return { data, error };
  },

  // Ride operations
  async createRideRequest(rideRequest: any) {
    const { data, error } = await supabase
      .from('ride_requests')
      .insert([rideRequest])
      .select()
      .single();
    return { data, error };
  },

  async getRideRequests(filters?: any) {
    let query = supabase.from('ride_requests').select('*');

    if (filters?.customerId) query = query.eq('customer_id', filters.customerId);
    if (filters?.driverId) query = query.eq('driver_id', filters.driverId);
    if (filters?.status) query = query.eq('status', filters.status);

    const { data, error } = await query.order('created_at', { ascending: false });
    return { data, error };
  },

  async getRideRequest(rideId: string) {
    const { data, error } = await supabase
      .from('ride_requests')
      .select('*')
      .eq('id', rideId)
      .single();
    return { data, error };
  },

  // Database-driven status updates for customer notifications
  async updateRideStatus(rideId: string, status: string, statusDetails?: any) {
    const timestamp = new Date().toISOString();
    const updateData: any = {
      status,
      updated_at: timestamp,
      ...statusDetails
    };

    const { data, error } = await supabase
      .from('ride_requests')
      .update(updateData)
      .eq('id', rideId)
      .select()
      .single();

    return { data, error };
  },

  // Store accepted request in database
  async acceptRideRequest(rideId: string, driverId: string, driverName: string, driverPhoto?: string, driverPlate?: string, driverRating?: string) {
    const timestamp = new Date().toISOString();

    // DEBUG: Log what we're about to update
    console.log(' acceptRideRequest DEBUG LOG:');
    console.log('   Ride ID:', rideId);
    console.log('   Driver ID:', driverId);
    console.log('   Driver Name:', driverName);
    console.log('   Driver Photo:', driverPhoto);
    console.log('   Driver Plate:', driverPlate, '(will be:', (driverPlate || 'N/A'), ')');
    console.log('   Driver Rating:', driverRating, '(will be:', (driverRating || '4.8'), ')');

    const updateData = {
      driver_id: driverId,
      driver_name: driverName,
      driver_photo: driverPhoto,
      driver_plate: driverPlate || 'N/A',
      driver_rating: driverRating || '4.8',
      status: 'accepted',
      accepted_at: timestamp,
      accepted_driver_id: driverId,
      updated_at: timestamp
    };

    console.log(' Update object:', updateData);

    const { data, error } = await supabase
      .from('ride_requests')
      .update(updateData)
      .eq('id', rideId)
      .select()
      .single();

    if (error) {
      console.error('❌ Error updating ride_requests:', error);
    } else {
      console.log('✅ Successfully updated ride_requests:', data);
    }

    return { data, error };
  },

  // Update driver's current status for the ride
  async updateDriverRideStatus(rideId: string, driverStatus: string, statusMessage?: string) {
    const timestamp = new Date().toISOString();
    const { data, error } = await supabase
      .from('ride_requests')
      .update({
        driver_status: driverStatus,
        driver_status_message: statusMessage,
        driver_status_updated_at: timestamp,
        updated_at: timestamp
      })
      .eq('id', rideId)
      .select()
      .single();

    return { data, error };
  },

  async updateRideRequest(rideId: string, updates: any) {
    const { data, error } = await supabase
      .from('ride_requests')
      .update(updates)
      .eq('id', rideId)
      .select()
      .single();
    return { data, error };
  },

  // Shared ride lobby operations
  async createLobby(lobby: any) {
    const { data, error } = await supabase
      .from('shared_ride_lobbies')
      .insert([lobby])
      .select()
      .single();
    return { data, error };
  },

  async getLobbyById(lobbyId: string) {
    const { data, error } = await supabase
      .from('shared_ride_lobbies')
      .select('*')
      .eq('id', lobbyId)
      .single();
    return { data, error };
  },

  async getLobbies(filters?: any) {
    let query = supabase.from('shared_ride_lobbies').select('*');

    if (filters?.status) query = query.eq('status', filters.status);
    if (filters?.pickupLocation) query = query.eq('pickup_location', filters.pickupLocation);

    const { data, error } = await query.order('created_at', { ascending: false });
    return { data, error };
  },

  async updateLobby(lobbyId: string, updates: any) {
    const { data, error } = await supabase
      .from('shared_ride_lobbies')
      .update(updates)
      .eq('id', lobbyId)
      .select()
      .single();
    return { data, error };
  },

  // Message operations
  async saveMessage(message: any) {
    const { data, error } = await supabase
      .from('messages')
      .insert([message])
      .select()
      .single();
    return { data, error };
  },

  async getMessages(senderId: string, receiverId: string) {
    const { data, error } = await supabase
      .from('messages')
      .select('*')
      .or(`and(sender_id.eq.${senderId},receiver_id.eq.${receiverId}),and(sender_id.eq.${receiverId},receiver_id.eq.${senderId})`)
      .order('created_at', { ascending: true });
    return { data, error };
  },

  async markMessageAsRead(messageId: string) {
    const { data, error } = await supabase
      .from('messages')
      .update({ read: true })
      .eq('id', messageId)
      .select()
      .single();
    return { data, error };
  },

  // Order operations
  async createOrder(order: any) {
    const { data, error } = await supabase
      .from('orders')
      .insert([order])
      .select()
      .single();
    return { data, error };
  },

  async getOrders(customerId: string) {
    const { data, error } = await supabase
      .from('orders')
      .select('*')
      .eq('customer_id', customerId)
      .order('created_at', { ascending: false });
    return { data, error };
  },

  // Get all orders with filters
  async getAllOrders(filters?: any) {
    let query = supabase.from('orders').select('*');

    if (filters?.restaurantId) query = query.eq('restaurant_id', filters.restaurantId);
    if (filters?.customerId) query = query.eq('customer_id', filters.customerId);
    if (filters?.status) query = query.eq('status', filters.status);
    if (filters?.orderNumber) query = query.eq('order_number', filters.orderNumber);
    if (filters?.customerEmail) query = query.eq('customer_email', filters.customerEmail);

    const { data, error } = await query.order('created_at', { ascending: false });
    return { data, error };
  },

  // Get order by ID
  async getOrderById(orderId: string) {
    const { data, error } = await supabase
      .from('orders')
      .select('*')
      .eq('id', orderId)
      .single();
    return { data, error };
  },

  // Get order by order number
  async getOrderByNumber(orderNumber: string) {
    const { data, error } = await supabase
      .from('orders')
      .select('*')
      .eq('order_number', orderNumber)
      .single();
    return { data, error };
  },

  // Get business orders (orders for a specific restaurant)
  async getBusinessOrders(restaurantId: string, filters?: any) {
    let query = supabase.from('orders').select('*').eq('restaurant_id', restaurantId);

    if (filters?.status) query = query.eq('status', filters.status);
    if (filters?.startDate) query = query.gte('created_at', filters.startDate);
    if (filters?.endDate) query = query.lte('created_at', filters.endDate);

    const { data, error } = await query.order('created_at', { ascending: false });
    return { data, error };
  },

  // Get pending orders for a business
  async getPendingOrders(restaurantId: string) {
    const { data, error } = await supabase
      .from('orders')
      .select('*')
      .eq('restaurant_id', restaurantId)
      .in('status', ['pending', 'preparing', 'ready', 'on-the-way'])
      .order('created_at', { ascending: true });
    return { data, error };
  },

  // Search orders by customer email
  async searchOrdersByCustomerEmail(customerEmail: string) {
    const { data, error } = await supabase
      .from('orders')
      .select('*')
      .ilike('customer_email', `%${customerEmail}%`)
      .order('created_at', { ascending: false });
    return { data, error };
  },

  // Get recent orders (last N orders)
  async getRecentOrders(limit: number = 10) {
    const { data, error } = await supabase
      .from('orders')
      .select('*')
      .order('created_at', { ascending: false })
      .limit(limit);
    return { data, error };
  },

  async updateOrder(orderId: string, updates: any) {
    const { data, error } = await supabase
      .from('orders')
      .update(updates)
      .eq('id', orderId)
      .select()
      .single();
    return { data, error };
  },

  // Delete order
  async deleteOrder(orderId: string) {
    const { data, error } = await supabase
      .from('orders')
      .delete()
      .eq('id', orderId);
    return { data, error };
  },

  // File uploads
  async uploadProfilePhoto(userId: string, file: File) {
    const fileExt = file.name.split('.').pop();
    const filePath = `${userId}/profile.${fileExt}`;

    const { data, error } = await supabase.storage
      .from('user_profiles')
      .upload(filePath, file, { upsert: true });

    if (error) return { data: null, error };

    const { data: publicUrlData } = supabase.storage
      .from('user_profiles')
      .getPublicUrl(filePath);

    return { data: publicUrlData, error: null };
  },

  async uploadRestaurantImage(restaurantId: string, file: File) {
    const fileExt = file.name.split('.').pop();
    const filePath = `${restaurantId}/image.${fileExt}`;

    const { data, error } = await supabase.storage
      .from('restaurants')
      .upload(filePath, file, { upsert: true });

    if (error) return { data: null, error };

    const { data: publicUrlData } = supabase.storage
      .from('restaurants')
      .getPublicUrl(filePath);

    return { data: publicUrlData, error: null };
  },

  // Order Processing Operations
  async createOrderProcessing(processing: any) {
    const { data, error } = await supabase
      .from('order_processing')
      .insert([processing])
      .select()
      .single();
    return { data, error };
  },

  async getOrderProcessing(orderId: string) {
    const { data, error } = await supabase
      .from('order_processing')
      .select('*')
      .eq('order_id', orderId)
      .single();
    return { data, error };
  },

  async getRestaurantProcessing(restaurantId: string, filters?: any) {
    let query = supabase
      .from('order_processing')
      .select('*')
      .eq('restaurant_id', restaurantId);

    if (filters?.status) query = query.eq('status', filters.status);
    if (filters?.startDate) query = query.gte('created_at', filters.startDate);
    if (filters?.endDate) query = query.lte('created_at', filters.endDate);

    const { data, error } = await query.order('created_at', { ascending: false });
    return { data, error };
  },

  async updateOrderProcessingStatus(orderId: string, status: string, updates?: any) {
    const timestamp = new Date().toISOString();
    const statusUpdateMap: { [key: string]: string } = {
      'received': 'received_at',
      'confirmed': 'confirmed_at',
      'preparing': 'preparing_started_at',
      'quality_check': 'quality_check_at',
      'ready': 'ready_at',
      'assigned_rider': 'rider_assigned_at',
      'on_the_way': 'delivery_started_at',
      'delivered': 'delivered_at',
      'completed': 'completed_at',
      'cancelled': 'cancelled_at',
    };

    const updateData: any = {
      status,
      updated_at: timestamp,
      ...updates,
    };

    // Auto-set timestamp field for this status
    const timestampField = statusUpdateMap[status];
    if (timestampField) {
      updateData[timestampField] = timestamp;
    }

    const { data, error } = await supabase
      .from('order_processing')
      .update(updateData)
      .eq('order_id', orderId)
      .select()
      .single();

    return { data, error };
  },

  async getProcessingByStatus(restaurantId: string, status: string) {
    const { data, error } = await supabase
      .from('order_processing')
      .select('*')
      .eq('restaurant_id', restaurantId)
      .eq('status', status)
      .order('created_at', { ascending: true });

    return { data, error };
  },

  async getActiveProcessing(restaurantId: string) {
    const { data, error } = await supabase
      .from('order_processing')
      .select('*')
      .eq('restaurant_id', restaurantId)
      .in('status', ['received', 'confirmed', 'preparing', 'quality_check', 'ready', 'assigned_rider', 'on_the_way'])
      .order('created_at', { ascending: true });

    return { data, error };
  },

  async getProcessingHistory(restaurantId: string, limit: number = 50) {
    const { data, error } = await supabase
      .from('order_processing')
      .select('*')
      .eq('restaurant_id', restaurantId)
      .in('status', ['delivered', 'completed', 'cancelled'])
      .order('completed_at', { ascending: false })
      .limit(limit);

    return { data, error };
  },

  async assignRiderToOrder(orderId: string, riderId: string, riderName: string) {
    const { data, error } = await supabase
      .from('order_processing')
      .update({
        assigned_rider_id: riderId,
        assigned_rider_name: riderName,
        updated_at: new Date().toISOString(),
      })
      .eq('order_id', orderId)
      .select()
      .single();

    return { data, error };
  },

  async recordQualityCheck(orderId: string, passed: boolean, issues?: any) {
    const { data, error } = await supabase
      .from('order_processing')
      .update({
        qa_passed: passed,
        quality_issues: issues || null,
        updated_at: new Date().toISOString(),
      })
      .eq('order_id', orderId)
      .select()
      .single();

    return { data, error };
  },

  async getProcessingStats(restaurantId: string, dateRange?: { start: string; end: string }) {
    let query = supabase
      .from('order_processing')
      .select('*', { count: 'exact' })
      .eq('restaurant_id', restaurantId);

    if (dateRange?.start) query = query.gte('created_at', dateRange.start);
    if (dateRange?.end) query = query.lte('created_at', dateRange.end);

    const { data, error, count } = await query;

    if (error) return { data: null, error };

    // Calculate statistics
    const stats = {
      totalOrders: count,
      completed: data?.filter(p => p.status === 'completed').length || 0,
      cancelled: data?.filter(p => p.status === 'cancelled').length || 0,
      averagePrepTime: 0,
      qualityIssues: data?.filter(p => !p.qa_passed).length || 0,
    };

    // Calculate average prep time
    const completedWithTime = data?.filter(p => p.actual_prep_time) || [];
    if (completedWithTime.length > 0) {
      const totalTime = completedWithTime.reduce((sum: number, p: any) => sum + (p.actual_prep_time || 0), 0);
      stats.averagePrepTime = Math.round(totalTime / completedWithTime.length);
    }

    return { data: stats, error: null };
  },

  // Real-time subscription for driver status updates
  subscribeToRideUpdates(rideId: string, callback: (data: any) => void) {
    console.log(` Setting up real-time subscription for ride: ${rideId}`);

    const channel = supabase
      .channel(`ride_${rideId}`)
      .on(
        'postgres_changes',
        {
          event: '*',
          schema: 'public',
          table: 'ride_requests',
          filter: `id=eq.${rideId}`
        },
        (payload) => {
          console.log(' Real-time update received:', payload);
          callback(payload.new);
        }
      )
      .subscribe((status) => {
        if (status === 'SUBSCRIBED') {
          console.log(`✅ Real-time subscription active for ride: ${rideId}`);
        } else if (status === 'CHANNEL_ERROR') {
          console.error(`❌ Subscription error for ride: ${rideId}`);
        }
      });

    // Return unsubscribe function
    return () => {
      console.log(` Unsubscribing from ride: ${rideId}`);
      supabase.removeChannel(channel);
    };
  },

  // Subscribe to accepted rides (for driver acceptance in real-time)
  subscribeToAcceptedRides(customerId: string, callback: (data: any) => void) {
    console.log(` Setting up real-time subscription for customer accepted rides: ${customerId}`);

    const channel = supabase
      .channel(`customer_${customerId}_rides`)
      .on(
        'postgres_changes',
        {
          event: 'UPDATE',
          schema: 'public',
          table: 'ride_requests',
          filter: `customer_id=eq.${customerId}`
        },
        (payload) => {
          // Only notify if driver has been assigned
          if (payload.new.accepted_driver_id) {
            console.log(' Driver accepted ride (real-time):', payload);
            callback(payload.new);
          }
        }
      )
      .subscribe((status) => {
        if (status === 'SUBSCRIBED') {
          console.log(`✅ Real-time subscription active for customer: ${customerId}`);
        } else if (status === 'CHANNEL_ERROR') {
          console.error(`❌ Subscription error for customer: ${customerId}`);
        }
      });

    return () => {
      console.log(` Unsubscribing from customer rides: ${customerId}`);
      supabase.removeChannel(channel);
    };
  },
};

import { createClient } from '@supabase/supabase-js';

// Initialize Supabase client
const supabaseUrl = import.meta.env.VITE_SUPABASE_URL;
const supabaseAnonKey = import.meta.env.VITE_SUPABASE_ANON_KEY;

console.log('[Supabase Init] Checking environment variables...');
console.log('[Supabase Init] VITE_SUPABASE_URL:', supabaseUrl ? '✅ Set' : '❌ Missing');
console.log('[Supabase Init] VITE_SUPABASE_ANON_KEY:', supabaseAnonKey ? '✅ Set' : '❌ Missing');

// Check if credentials are configured
if (!supabaseUrl || !supabaseAnonKey) {
  const missing = [];
  if (!supabaseUrl) missing.push('VITE_SUPABASE_URL');
  if (!supabaseAnonKey) missing.push('VITE_SUPABASE_ANON_KEY');

  const errorMsg =
    `\n\n❌ SUPABASE CONFIGURATION ERROR\n` +
    `━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n` +
    `Missing environment variables: ${missing.join(', ')}\n\n` +
    `How to fix:\n` +
    `1. Open the file: .env.local (in project root)\n` +
    `2. Make sure it contains:\n` +
    `   VITE_SUPABASE_URL=https://azmzuucnfqqymnunntmw.supabase.co\n` +
    `   VITE_SUPABASE_ANON_KEY=your_actual_key_here\n\n` +
    `3. Get the key from: Supabase Dashboard → Settings → API\n` +
    `4. STOP the dev server (Ctrl+C)\n` +
    `5. DELETE the .vite cache folder in node_modules\n` +
    `6. RESTART with: npm run dev\n` +
    `━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n\n`;

  console.error(errorMsg);
  throw new Error(`Missing Supabase credentials: ${missing.join(', ')}`);
}

console.log('[Supabase Init] ✅ All credentials loaded successfully');

export const supabase = createClient(
  supabaseUrl,
  supabaseAnonKey
);

